rty\n * @throws {RangeError} use `yyyy` instead of `YYYY` for formatting years; see: https://github.com/date-fns/date-fns/blob/master/docs/unicodeTokens.md\n * @throws {RangeError} use `yy` instead of `YY` for formatting years; see: https://github.com/date-fns/date-fns/blob/master/docs/unicodeTokens.md\n * @throws {RangeError} use `d` instead of `D` for formatting days of the month; see: https://github.com/date-fns/date-fns/blob/master/docs/unicodeTokens.md\n * @throws {RangeError} use `dd` instead of `DD` for formatting days of the month; see: https://github.com/date-fns/date-fns/blob/master/docs/unicodeTokens.md\n * @throws {RangeError} format string contains an unescaped latin alphabet character\n *\n * @example\n * // Match 11 February 2014 from middle-endian format:\n * const result = isMatch('02/11/2014', 'MM/dd/yyyy')\n * //=> true\n *\n * @example\n * // Match 28th of February in Esperanto locale in the context of 2010 year:\n * import eo from 'date-fns/locale/eo'\n * const result = isMatch('28-a de februaro', \"do 'de' MMMM\", {\n *   locale: eo\n * })\n * //=> true\n */\nexport default function isMatch(dateString, formatString, options) {\n  requiredArgs(2, arguments);\n  return isValid(parse(dateString, formatString, new Date(), options));\n}","import { isValid } from \"date-fns\";\nimport { observer } from \"mobx-react\";\nimport React from \"react\";\nimport { DatePicker } from \"../../Common/DatePicker/DatePicker\";\n\nexport const DateTimeInput = observer(({ value, range, time, onChange }) => {\n  const onValueChange = React.useCallback(\n    (selectedDate) => {\n      let value;\n\n      if (Array.isArray(selectedDate)) {\n        const [min, max] = selectedDate\n          .map((d) => (d ? new Date(d) : null))\n          .map((d) => (isValid(d) ? d.toISOString() : null));\n\n        value = { min, max };\n      } else {\n        value = selectedDate?.toISOString();\n      }\n\n      onChange(value);\n    },\n    [onChange],\n  );\n\n  const dateValue = React.useMemo(() => {\n    if (range) {\n      const { min, max } = value ?? {};\n\n      return [min, max]\n        .map((d) => (d === null ? undefined : d))\n        .map((d) => new Date(d))\n        .map((d) => (isValid(d) ? d : undefined));\n    }\n    const date = new Date(value === null ? undefined : value);\n\n    return isValid(date) ? date : undefined;\n  }, [range, value]);\n\n  return (\n    <DatePicker size=\"small\" value={dateValue} selectRange={range} showTime={time === true} onChange={onValueChange} />\n  );\n});\n\nexport const DateFields = (extraProps) => {\n  return [\n    {\n      key: \"less\",\n      label: \"is before\",\n      valueType: \"single\",\n      input: (props) => <DateTimeInput {...props} {...(extraProps ?? {})} />,\n    },\n    {\n      key: \"greater\",\n      label: \"is after\",\n      valueType: \"single\",\n      input: (props) => <DateTimeInput {...props} {...(extraProps ?? {})} />,\n    },\n    {\n      key: \"in\",\n      label: \"is between\",\n      valueType: \"range\",\n      input: (props) => <DateTimeInput range {...props} {...(extraProps ?? {})} />,\n    },\n    {\n      key: \"not_in\",\n      label: \"not between\",\n      valueType: \"range\",\n      input: (props) => <DateTimeInput range {...props} {...(extraProps ?? {})} />,\n    },\n  ];\n};\n\nexport const DateFilter = [...DateFields()];\n","import { DateFields } from \"./Date\";\n\nexport const DatetimeFilter = [...DateFields({ time: true })];\n","import { observer } from \"mobx-react\";\nimport React from \"react\";\nimport { FilterDropdown } from \"../FilterDropdown\";\n// import { Common } from \"./Common\";\n\nexport const VariantSelect = observer(({ filter, schema, onChange, multiple, value }) => {\n  if (!schema) return <></>;\n  const { items } = schema;\n\n  const selectedValue = (() => {\n    if (!multiple) {\n      return Array.isArray(value) ? value[0] : value;\n    }\n    return Array.isArray(value) ? value : value ?? [];\n  })();\n\n  const FilterItem = filter.cellView?.FilterItem;\n\n  return (\n    <FilterDropdown\n      items={items}\n      value={selectedValue}\n      multiple={multiple}\n      optionRender={FilterItem}\n      outputFormat={\n        multiple\n          ? (value) => {\n              return value ? [].concat(value) : [];\n            }\n          : undefined\n      }\n      onChange={(value) => onChange(value)}\n    />\n  );\n});\n\nexport const ListFilter = [\n  {\n    key: \"contains\",\n    label: \"contains\",\n    valueType: \"single\",\n    input: (props) => <VariantSelect {...props} multiple />,\n  },\n  {\n    key: \"not_contains\",\n    label: \"not contains\",\n    valueType: \"single\",\n    input: (props) => <VariantSelect {...props} multiple />,\n  },\n  // ... Common,\n];\n","import React from \"react\";\nimport Input from \"../Common/Input/Input\";\n\nexport const FilterInput = ({ value, type, onChange, placeholder, schema, style }) => {\n  const inputRef = React.useRef();\n  const onChangeHandler = () => {\n    const value = inputRef.current?.value ?? inputRef.current?.input?.value;\n\n    onChange(value);\n  };\n\n  return (\n    <Input\n      size=\"small\"\n      type={type}\n      value={value ?? \"\"}\n      ref={inputRef}\n      placeholder={placeholder}\n      onChange={onChangeHandler}\n      style={style}\n      {...(schema ?? {})}\n    />\n  );\n};\n","import { observer } from \"mobx-react\";\nimport React from \"react\";\nimport { isDefined } from \"../../../utils/utils\";\nimport { FilterInput } from \"../FilterInput\";\n\nconst valueFilter = (value) => {\n  if (isDefined(value)) {\n    if (typeof value === \"number\") {\n      return value;\n    }\n    if (typeof value === \"string\") {\n      return value.replace(/([^\\d.,]+)/, \"\");\n    }\n    return value || null;\n  }\n\n  return null;\n};\n\nconst NumberInput = observer(({ onChange, ...rest }) => {\n  return <FilterInput {...rest} type=\"number\" onChange={(value) => onChange(valueFilter(value))} />;\n});\n\nconst RangeInput = observer(({ schema, value, onChange }) => {\n  const min = value?.min ?? null;\n  const max = value?.max ?? null;\n\n  const onValueChange = (newValue) => {\n    console.log({ newValue });\n    onChange(newValue);\n  };\n\n  const onChangeMin = (newValue) => {\n    onValueChange({ min: Number(newValue), max });\n  };\n\n  const onChangeMax = (newValue) => {\n    onValueChange({ min, max: Number(newValue) });\n  };\n\n  return (\n    <>\n      <NumberInput placeholder=\"Min\" value={min} onChange={onChangeMin} schema={schema} style={{ flex: 1 }} />\n      <span style={{ padding: \"0 10px\" }}>and</span>\n      <NumberInput placeholder=\"Max\" value={max} onChange={onChangeMax} schema={schema} style={{ flex: 1 }} />\n    </>\n  );\n});\n\nexport const NumberFilter = [\n  {\n    key: \"equal\",\n    label: \"=\",\n    valueType: \"single\",\n    input: (props) => <NumberInput {...props} />,\n  },\n  {\n    key: \"not_equal\",\n    label: \"≠\",\n    valueType: \"single\",\n    input: (props) => <NumberInput {...props} />,\n  },\n  {\n    key: \"less\",\n    label: \"<\",\n    valueType: \"single\",\n    input: (props) => <NumberInput {...props} />,\n  },\n  {\n    key: \"greater\",\n    label: \">\",\n    valueType: \"single\",\n    input: (props) => <NumberInput {...props} />,\n  },\n  {\n    key: \"less_or_equal\",\n    label: \"≤\",\n    valueType: \"single\",\n    input: (props) => <NumberInput {...props} />,\n  },\n  {\n    key: \"greater_or_equal\",\n    label: \"≥\",\n    valueType: \"single\",\n    input: (props) => <NumberInput {...props} />,\n  },\n  {\n    key: \"in\",\n    label: \"is between\",\n    valueType: \"range\",\n    input: (props) => <RangeInput {...props} />,\n  },\n  {\n    key: \"not_in\",\n    label: \"not between\",\n    valueType: \"range\",\n    input: (props) => <RangeInput {...props} />,\n  },\n];\n","import { observer } from \"mobx-react\";\nimport React from \"react\";\nimport { FilterInput } from \"../FilterInput\";\n\nconst BaseInput = observer(({ value, onChange, placeholder }) => {\n  return (\n    <FilterInput type=\"text\" value={value} onChange={onChange} style={{ fontSize: 14 }} placeholder={placeholder} />\n  );\n});\n\nexport const StringFilter = [\n  {\n    key: \"contains\",\n    label: \"contains\",\n    valueType: \"single\",\n    input: (props) => <BaseInput {...props} />,\n  },\n  {\n    key: \"not_contains\",\n    label: \"not contains\",\n    valueType: \"single\",\n    input: (props) => <BaseInput {...props} />,\n  },\n  {\n    key: \"regex\",\n    label: \"regex\",\n    valueType: \"single\",\n    input: (props) => <BaseInput {...props} />,\n  },\n  {\n    key: \"equal\",\n    label: \"equal\",\n    valueType: \"single\",\n    input: (props) => <BaseInput {...props} />,\n  },\n  {\n    key: \"not_equal\",\n    label: \"not equal\",\n    valueType: \"single\",\n    input: (props) => <BaseInput {...props} />,\n  },\n];\n","const EXCLUDED_FILTER_OPERATIONS = {\n  DE: [\"contains\", \"not_contains\", \"regex\"],\n  dm: [\"similar_to\"],\n};\n\nexport const allowedFilterOperations = (operationsList, context = \"\") => {\n  return context in EXCLUDED_FILTER_OPERATIONS\n    ? operationsList.filter((op) => !EXCLUDED_FILTER_OPERATIONS[context].includes(op.key))\n    : operationsList;\n};\n","import { observer } from \"mobx-react\";\nimport { getRoot } from \"mobx-state-tree\";\nimport React, { useCallback, useMemo } from \"react\";\nimport { Elem } from \"../../../utils/bem\";\nimport { debounce } from \"../../../utils/debounce\";\nimport { FilterDropdown } from \"../FilterDropdown\";\nimport * as FilterInputs from \"../types\";\nimport { allowedFilterOperations } from \"../types/Utility\";\nimport { Common } from \"../types/Common\";\n\n/** @typedef {{\n * type: keyof typeof FilterInputs,\n * width: number\n * }} FieldConfig */\n\n/**\n *\n * @param {{field: FieldConfig}} param0\n */\nexport const FilterOperation = observer(({ filter, field, operator, value }) => {\n  const cellView = filter.cellView;\n  const types = cellView?.customOperators ?? [\n    ...(FilterInputs[filter.filter.currentType] ?? FilterInputs.String),\n    ...Common,\n  ];\n\n  const selected = useMemo(() => {\n    let result;\n\n    if (operator) {\n      result = types.find((t) => t.key === operator);\n    }\n\n    if (!result) {\n      result = types[0];\n    }\n\n    filter.setOperator(result.key);\n    return result;\n  }, [operator, types, filter]);\n\n  const saveFilter = useCallback(\n    debounce(() => {\n      filter.save(true);\n    }, 300),\n    [filter],\n  );\n\n  const onChange = (newValue) => {\n    filter.setValue(newValue);\n    saveFilter();\n  };\n\n  const onOperatorSelected = (selectedKey) => {\n    filter.setOperator(selectedKey);\n  };\n  const availableOperators = filter.cellView?.filterOperators;\n  const Input = selected?.input;\n  const operatorList = allowedFilterOperations(types, getRoot(filter)?.SDK?.type);\n  const operators = operatorList.map(({ key, label }) => ({ value: key, label }));\n\n  return Input ? (\n    <>\n      <Elem block=\"filter-line\" name=\"column\" mix=\"operation\">\n        <FilterDropdown\n          placeholder=\"Condition\"\n          value={filter.operator}\n          disabled={types.length === 1}\n          items={availableOperators ? operators.filter((op) => availableOperators.includes(op.value)) : operators}\n          onChange={onOperatorSelected}\n        />\n      </Elem>\n      <Elem block=\"filter-line\" name=\"column\" mix=\"value\">\n        <Input\n          {...field}\n          key={`${filter.filter.id}-${filter.filter.currentType}`}\n          schema={filter.schema}\n          filter={filter}\n          value={value}\n          onChange={onChange}\n        />\n      </Elem>\n    </>\n  ) : null;\n});\n","import { observer } from \"mobx-react\";\nimport React, { Fragment } from \"react\";\nimport { FaTrash } from \"react-icons/fa\";\nimport { BemWithSpecifiContext } from \"../../../utils/bem\";\nimport { Button } from \"../../Common/Button/Button\";\nimport { Icon } from \"../../Common/Icon/Icon\";\nimport { Tag } from \"../../Common/Tag/Tag\";\nimport { FilterDropdown } from \"../FilterDropdown\";\nimport \"./FilterLine.scss\";\nimport { FilterOperation } from \"./FilterOperation\";\n\nconst { Block, Elem } = BemWithSpecifiContext();\n\nconst Conjunction = observer(({ index, view }) => {\n  return (\n    <FilterDropdown\n      items={[\n        { value: \"and\", label: \"And\" },\n        { value: \"or\", label: \"Or\" },\n      ]}\n      disabled={index > 1}\n      value={view.conjunction}\n      style={{ textAlign: \"right\" }}\n      onChange={(value) => view.setConjunction(value)}\n    />\n  );\n});\n\nconst GroupWrapper = ({ children, wrap = false }) => {\n  return wrap ? <Elem name=\"group\">{children}</Elem> : children;\n};\n\nexport const FilterLine = observer(({ filter, availableFilters, index, view, sidebar, dropdownClassName }) => {\n  return (\n    <Block name=\"filter-line\" tag={Fragment}>\n      <GroupWrapper wrap={sidebar}>\n        <Elem name=\"column\" mix=\"conjunction\">\n          {index === 0 ? (\n            <span style={{ fontSize: 12, paddingRight: 5 }}>Where</span>\n          ) : (\n            <Conjunction index={index} view={view} />\n          )}\n        </Elem>\n        <Elem name=\"column\" mix=\"field\">\n          <FilterDropdown\n            placeholder=\"Column\"\n            defaultValue={filter.filter.id}\n            items={availableFilters}\n            width={80}\n            dropdownWidth={120}\n            dropdownClassName={dropdownClassName}\n            onChange={(value) => filter.setFilterDelayed(value)}\n            optionRender={({ item: { original: filter } }) => (\n              <Elem name=\"selector\">\n                {filter.field.title}\n                {filter.field.parent && (\n                  <Tag size=\"small\" className=\"filters-data-tag\" color=\"#1d91e4\" style={{ marginLeft: 7 }}>\n                    {filter.field.parent.title}\n                  </Tag>\n                )}\n              </Elem>\n            )}\n          />\n        </Elem>\n      </GroupWrapper>\n      <GroupWrapper wrap={sidebar}>\n        <FilterOperation filter={filter} value={filter.currentValue} operator={filter.operator} field={filter.field} />\n      </GroupWrapper>\n      <Elem name=\"remove\">\n        <Button\n          type=\"link\"\n          onClick={(e) => {\n            e.stopPropagation();\n            filter.delete();\n          }}\n          icon={<Icon icon={FaTrash} size={12} />}\n        />\n      </Elem>\n    </Block>\n  );\n});\n","import { inject } from \"mobx-react\";\nimport React from \"react\";\nimport { FaCaretSquareRight, FaPlus } from \"react-icons/fa\";\nimport { Block, cn, Elem } from \"../../utils/bem\";\nimport { Button } from \"../Common/Button/Button\";\nimport { Icon } from \"../Common/Icon/Icon\";\nimport { Tooltip } from \"../Common/Tooltip/Tooltip\";\nimport { FilterLine } from \"./FilterLine/FilterLine\";\nimport \"./Filters.scss\";\n\nconst injector = inject(({ store }) => ({\n  store,\n  views: store.viewsStore,\n  currentView: store.currentView,\n  filters: store.currentView?.currentFilters ?? [],\n}));\n\nexport const Filters = injector(({ views, currentView, filters }) => {\n  const { sidebarEnabled } = views;\n\n  const fields = React.useMemo(\n    () =>\n      currentView.availableFilters.reduce((res, filter) => {\n        const target = filter.field.target;\n        const groupTitle = target\n          .split(\"_\")\n          .map((s) =>\n            s\n              .split(\"\")\n              .map((c, i) => (i === 0 ? c.toUpperCase() : c))\n              .join(\"\"),\n          )\n          .join(\" \");\n\n        const group = res[target] ?? {\n          id: target,\n          title: groupTitle,\n          options: [],\n        };\n\n        group.options.push({\n          value: filter.id,\n          title: f