tch({ type: \"pause\" }),\n    onTimeUpdate: () => dispatch({ type: \"current\", payload: media.current.currentTime }),\n    onDurationChange: () => dispatch({ type: \"duration\", payload: media.current.duration }),\n    onCanPlay: () => dispatch({ type: \"loaded\" }),\n    onProgress: () => dispatch({ type: \"buffer\", payload: media.current.buffered }),\n    onError: () => dispatch({ type: \"error\" }),\n  };\n\n  useEffect(() => {\n    if (!isFF(FF_LSDV_4711)) return;\n\n    // force reload on error if the source previously loaded,\n    // as it may just require a new presigned url\n    if (state.resetSource > 0) {\n      dispatch({ type: \"resetSource\" });\n      hasReloaded.current = true;\n      media.current.load();\n    }\n  }, [state.resetSource]);\n\n  useEffect(() => {\n    if (!isFF(FF_LSDV_4711)) return;\n\n    // if the source was reloaded due to error, we need to wait for it to load\n    // before we can set the current time and play if it was previously playing\n    if (hasReloaded.current && state.loaded) {\n      hasReloaded.current = false;\n      media.current.currentTime = currentTimeRef.current;\n\n      if (wasPlaying.current) media.current.play();\n    }\n  }, [state.loaded]);\n\n  const showError = isFF(FF_LSDV_4711) ? !state.resetSource && state.error : state.error;\n\n  return enabled ? (\n    <Block name=\"player\" mod={{ video }} onClick={(e) => e.stopPropagation()}>\n      {video && <MediaSource type=\"video\" onClick={togglePlay} {...mediaProps} />}\n      {showError ? (\n        <Elem name=\"loading\">Unable to play</Elem>\n      ) : state.loaded ? (\n        <Elem name=\"playback\">\n          <Elem name=\"controls\" tag={Space} spread>\n            <Space size=\"small\">\n              <Elem name=\"play\" onClick={togglePlay}>\n                {state.playing ? <FaPause /> : <FaPlay />}\n              </Elem>\n              {!video && <Elem name=\"track\">{filename(src)}</Elem>}\n            </Space>\n            <Elem tag={Space} size=\"small\" name=\"time\">\n              <Duration value={state.currentTime} format={format} />\n              {\" / \"}\n              <Duration value={state.duration} format={format} />\n            </Elem>\n          </Elem>\n\n          <MediaSeeker\n            video={video}\n            currentTime={state.currentTime}\n            duration={state.duration}\n            buffer={state.buffer}\n            onSeekStart={onSeekStart}\n            onSeekEnd={onSeekEnd}\n            onChange={onSeek}\n          />\n        </Elem>\n      ) : (\n        <Elem name=\"loading\">\n          <Spinner size=\"24\" />\n        </Elem>\n      )}\n\n      {!video && <MediaSource type=\"audio\" {...mediaProps} ref={media} />}\n    </Block>\n  ) : (\n    <Block\n      name=\"player\"\n      onClick={(e) => {\n        e.stopPropagation();\n        setEnabled(true);\n        waitForPlayer();\n      }}\n    >\n      <Elem name=\"controls\" tag={Space} spread>\n        <Space size=\"small\">\n          <Elem name=\"play\">\n            <FaPlay />\n          </Elem>\n          <Elem name=\"track\">Click to load</Elem>\n        </Space>\n        <Elem tag={Space} size=\"small\" name=\"time\" />\n      </Elem>\n    </Block>\n  );\n};\n\nconst MediaSource = forwardRef(({ type = \"audio\", src, ...props }, ref) => {\n  return (\n    <Elem {...mediaDefaultProps} name=\"media\" tag={type} ref={ref} {...props}>\n      <source src={src} />\n    </Elem>\n  );\n});\n","import { MediaPlayer } from \"../Common/MediaPlayer/MediaPlayer\";\n\nexport const AudioCell = (column) => {\n  return <MediaPlayer src={column.value} />;\n};\n\nAudioCell.style = {\n  width: 50,\n  minWidth: 240,\n};\n\n/* Audio Plus */\n\nexport const AudioPlusCell = (column) => {\n  return <MediaPlayer src={column.value} />;\n};\n\nAudioPlusCell.style = {\n  width: 240,\n  minWidth: 240,\n};\n\nAudioPlusCell.userSelectable = false;\n","import React from \"react\";\nimport { Tag } from \"../Common/Tag/Tag\";\n\nconst parseBoolean = (value) => {\n  if ([true, 1, \"true\", \"1\", \"yes\"].includes(value) || !!value === true) {\n    return true;\n  }\n  return false;\n};\n\nexport const BooleanCell = (column) => {\n  const boolValue = parseBoolean(column.value);\n\n  if (boolValue === true) {\n    return <Tag color=\"#80c70d\">true</Tag>;\n  }\n  if (boolValue === false) {\n    return <Tag color=\"#de3301\">false</Tag>;\n  }\n\n  return null;\n};\n\nBooleanCell.userSelectable = false;\n","import { format, isValid } from \"date-fns\";\nexport const dateTimeFormat = \"MMM dd yyyy, HH:mm:ss\";\n\nexport const DateTimeCell = (column) => {\n  const date = new Date(column.value);\n\n  return column.value ? (\n    <div style={{ whiteSpace: \"nowrap\" }}>{isValid(date) ? format(date, dateTimeFormat) : \"\"}</div>\n  ) : (\n    \"\"\n  );\n};\n\nDateTimeCell.displayType = false;\n","import type { APIAnnotation, APIPrediction, APITask, LSFAnnotation, LSFTaskData } from \"../types/Task\";\nimport { FF_LSDV_5035, isFF } from \"../utils/feature-flags\";\n\n/**\n * Converts the task from the server format to the\n * format supported by the LS frontend\n * @param {import(\"../stores/Tasks\").TaskModel} task\n * @private\n */\nexport const taskToLSFormat = (task: APITask): LSFTaskData | void => {\n  if (!task) return;\n\n  const result: LSFTaskData = {\n    ...task,\n    annotations: [],\n    predictions: [],\n    createdAt: task.created_at,\n    // isLabeled: task.is_labeled, // @todo why?\n  };\n\n  if (task.annotations) {\n    result.annotations = task.annotations.map(annotationToLSF);\n  }\n\n  if (task.predictions) {\n    result.predictions = task.predictions.map(predictionToLSF);\n  }\n\n  return result;\n};\n\nexport const annotationToLSF = (annotation: APIAnnotation) => {\n  const createdDate = isFF(FF_LSDV_5035) ? annotation.draft_created_at || annotation.created_at : annotation.created_at;\n\n  return {\n    ...annotation,\n    id: undefined,\n    pk: String(annotation.id),\n    createdAgo: annotation.created_ago,\n    createdBy: annotation.created_username,\n    createdDate,\n    leadTime: annotation.lead_time ?? 0,\n    skipped: annotation.was_cancelled ?? false,\n  };\n};\n\nexport const predictionToLSF = (prediction: APIPrediction) => {\n  return {\n    ...prediction,\n    id: undefined,\n    pk: String(prediction.id),\n    createdAgo: prediction.created_ago,\n    createdBy: prediction.model_version?.trim() ?? \"\",\n    createdDate: prediction.created_at,\n  };\n};\n\nexport const annotationToServer = (annotation: LSFAnnotation): APIAnnotation => {\n  return {\n    ...annotation,\n    id: Number(annotation.pk),\n    created_ago: annotation.createdAgo,\n    created_username: annotation.createdBy,\n    created_at: new Date().toISOString(),\n    lead_time: annotation.leadTime,\n  };\n};\n\nexport const getAnnotationSnapshot = (c: LSFAnnotation) => ({\n  id: c.id,\n  pk: c.pk,\n  result: c.serializeAnnotation(),\n  leadTime: c.leadTime,\n  userGenerate: !!c.userGenerate,\n  sentUserGenerate: !!c.sentUserGenerate,\n});\n","import { inject, observer } from \"mobx-react\";\nimport React from \"react\";\nimport { taskToLSFormat } from \"../../../sdk/lsf-utils\";\nimport { Block } from \"../../../utils/bem\";\nimport { FF_LSDV_4711, isFF } from \"../../../utils/feature-flags\";\nimport { Spinner } from \"../Spinner\";\nimport \"./AnnotationPreview.scss\";\n\nconst imgDefaultProps = {};\n\nif (isFF(FF_LSDV_4711)) imgDefaultProps.crossOrigin = \"anonymous\";\n\nconst wait = (timeout) => new Promise((resolve) => setTimeout(resolve, timeout));\n\nclass PreviewGenerator {\n  static getInstance(labelingConfig) {\n    if (PreviewGenerator._instance) return PreviewGenerator._instance;\n\n    return (PreviewGenerator._instance = new PreviewGenerator(labelingConfig));\n  }\n\n  constructor(labelingConfig) {\n    this.loaded = false;\n    this.running = false;\n    this.queue = [];\n\n    this.root = document.querySelector(\".offscreen-lsf\");\n\n    this.lsf = new window.LabelStudio(this.root, {\n      user: { id: 1 },\n      interfaces: [],\n      config: labelingConfig ?? \"\",\n      onLabelStudioLoad: () => {\n        this.loaded = true;\n        this.startQueue();\n      },\n    });\n  }\n\n  generatePreview(task, annotation) {\n    return new Promise((resolve) => {\n      this.queue.push({\n        task,\n        annotation,\n        resolve,\n      });\n\n      this.startQueue();\n    });\n  }\n\n  async startQueue() {\n    if (this.loaded === false) return;\n    if (this.running === true) return;\n    if (this.queue.length === 0) return;\n\n    this.running = true;\n    await this.processJob();\n    this.running = false;\n  }\n\n  async processJob() {\n    const { task: taskRaw, annotation, resolve } = this.queue.shift();\n\n    const task = {\n      id: taskRaw.id,\n      annotations: taskRaw.annotations,\n      predictions: taskRaw.predictions,\n      data: taskRaw.data,\n    };\n\n    this.lsf.resetState();\n    this.lsf.assignTask(task);\n    this.lsf.initializeStore(taskToLSFormat(task));\n    this.lsf.annotationStore.selectAnnotation(annotation.pk ?? annotation.id);\n\n    await wait(1500);\n    const preview = await this.createPreviews(5);\n\n    resolve(preview);\n\n    if (this.queue.length) {\n      await this.processJob();\n    }\n  }\n\n  async createPreviews(attempts) {\n    if (attempts === 0) return;\n\n    try {\n      return this.lsf.annotationStore.selected.generatePreviews();\n    } catch (err) {\n      await wait(1000);\n      return this.createPreviews(attempts - 1);\n    }\n  }\n}\n\nconst injector = inject(({ store }) => {\n  return {\n    labelingConfig: store?.labelingConfig,\n  };\n});\n\nexport const AnnotationPreview = injector(\n  observer(({ labelingConfig, name, task, annotation, style, ...props }) => {\n    const generator = React.useMemo(() => {\n      if (labelingConfig) return PreviewGenerator.getInstance(labelingConfig);\n    }, [labelingConfig]);\n\n    const [preview, setPreview] = R