stContext = createContext();\n\nStickyListContext.displayName = \"StickyListProvider\";\n\nconst ItemWrapper = ({ data, index, style }) => {\n  const { Renderer, stickyItems } = data;\n\n  if (stickyItems?.includes(index) === true) {\n    return null;\n  }\n\n  return <Renderer index={index} style={style} />;\n};\n\nconst StickyList = observer(\n  forwardRef((props, listRef) => {\n    const {\n      children,\n      stickyComponent,\n      stickyItems,\n      stickyItemsHeight,\n      totalCount,\n      isItemLoaded,\n      loadMore,\n      initialScrollOffset,\n      ...rest\n    } = props;\n\n    const itemData = {\n      Renderer: children,\n      StickyComponent: stickyComponent,\n      stickyItems,\n      stickyItemsHeight,\n    };\n\n    const itemSize = (index) => {\n      if (stickyItems.includes(index)) {\n        return stickyItemsHeight[index] ?? rest.itemHeight;\n      }\n      return rest.itemHeight;\n    };\n\n    return (\n      <StickyListContext.Provider value={itemData}>\n        <TableElem tag={AutoSizer} name=\"auto-size\">\n          {({ width, height }) => (\n            <InfiniteLoader\n              ref={listRef}\n              itemCount={totalCount}\n              loadMoreItems={loadMore}\n              isItemLoaded={isItemLoaded}\n              threshold={5}\n              minimumBatchSize={30}\n            >\n              {({ onItemsRendered, ref }) => (\n                <TableElem\n                  name=\"virual\"\n                  tag={VariableSizeList}\n                  {...rest}\n                  ref={ref}\n                  width={width}\n                  height={height}\n                  itemData={itemData}\n                  itemSize={itemSize}\n                  onItemsRendered={onItemsRendered}\n                  initialScrollOffset={initialScrollOffset?.(height) ?? 0}\n                >\n                  {ItemWrapper}\n                </TableElem>\n              )}\n            </InfiniteLoader>\n          )}\n        </TableElem>\n      </StickyListContext.Provider>\n    );\n  }),\n);\n\nStickyList.displayName = \"StickyList\";\n\nconst innerElementType = forwardRef(({ children, ...rest }, ref) => {\n  return (\n    <StickyListContext.Consumer>\n      {({ stickyItems, stickyItemsHeight, StickyComponent }) => (\n        <div ref={ref} {...rest}>\n          {stickyItems.map((index) => (\n            <TableElem\n              name=\"sticky-header\"\n              tag={StickyComponent}\n              key={index}\n              index={index}\n              style={{\n                height: stickyItemsHeight[index],\n                top: index * stickyItemsHeight[index],\n              }}\n            />\n          ))}\n\n          {children}\n        </div>\n      )}\n    </StickyListContext.Consumer>\n  );\n});\n\nconst TaskSourceView = ({ content, onTaskLoad, sdkType }) => {\n  const [source, setSource] = useState(content);\n\n  useEffect(() => {\n    onTaskLoad().then((response) => {\n      const formatted = {\n        id: response.id,\n        data: response.data,\n      };\n\n      if (sdkType !== \"DE\") {\n        formatted.annotations = response.annotations ?? [];\n        formatted.predictions = response.predictions ?? [];\n      }\n      setSource(formatted);\n    });\n  }, []);\n\n  return <pre>{source ? JSON.stringify(source, null, \"  \") : null}</pre>;\n};\n","import { MediaPlayer } from \"../Common/MediaPlayer/MediaPlayer\";\n\nexport const AudioDataGroup = ({ value }) => {\n  const style = {\n    padding: 10,\n    height: AudioDataGroup.height,\n    boxSizing: \"content-box\",\n  };\n\n  return (\n    <div style={style}>\n      <MediaPlayer src={value} />\n    </div>\n  );\n};\n\nAudioDataGroup.height = 32;\n","import { getRoot } from \"mobx-state-tree\";\nimport { AnnotationPreview } from \"../Common/AnnotationPreview/AnnotationPreview\";\nimport { Block } from \"../../utils/bem\";\n\nexport const ImageDataGroup = (column) => {\n  const {\n    value,\n    original,\n    field: { alias },\n  } = column;\n  const root = getRoot(original);\n\n  return original.total_annotations === 0 || !root.showPreviews ? (\n    <Block name=\"grid-image-wrapper\">\n      <img src={value} width=\"auto\" height={ImageDataGroup.height} alt=\"\" />\n    </Block>\n  ) : (\n    <AnnotationPreview\n      task={original}\n      annotation={original.annotations[0]}\n      config={getRoot(original).SDK}\n      name={alias}\n      width=\"100%\"\n      size=\"large\"\n      fallbackImage={value}\n      height={ImageDataGroup.height}\n    />\n  );\n};\n\nImageDataGroup.height = 150;\n","import { format, isValid } from \"date-fns\";\nimport { dateTimeFormat } from \"../CellViews/DateTimeCell\";\n\nexport const valueToString = (value) => {\n  if (typeof value === \"string\") return value;\n  /* if undefined or null we'll treat it as empty string */\n  if (value === undefined || value === null) return \"\";\n  if (value instanceof Date && isValid(value)) return format(value, dateTimeFormat);\n\n  try {\n    /* JSON.stringify will handle JSON and non-strings, non-null, non-undefined */\n    return JSON.stringify(value);\n  } catch {\n    return \"Error: Invalid JSON\";\n  }\n};\n\nexport const TextDataGroup = ({ value }) => {\n  const output = valueToString(value);\n  const style = {\n    padding: 5,\n    height: TextDataGroup.height,\n    overflow: \"hidden\",\n    whiteSpace: \"nowrap\",\n    textOverflow: \"ellipsis\",\n  };\n\n  return (\n    <div style={style} title={output}>\n      {output}\n    </div>\n  );\n};\n\nTextDataGroup.height = 32;\n","// extracted by mini-css-extract-plugin\nexport default {\"grid-view\":\"dm-grid-view\",\"grid-view__resize\":\"dm-grid-view__resize\",\"grid-view__list\":\"dm-grid-view__list\",\"grid-view_columnCount_1\":\"dm-grid-view_columnCount_1\",\"grid-view__cell\":\"dm-grid-view__cell\",\"grid-view_columnCount_2\":\"dm-grid-view_columnCount_2\",\"grid-view_columnCount_3\":\"dm-grid-view_columnCount_3\",\"grid-view_columnCount_4\":\"dm-grid-view_columnCount_4\",\"grid-view_columnCount_5\":\"dm-grid-view_columnCount_5\",\"grid-view_columnCount_6\":\"dm-grid-view_columnCount_6\",\"grid-view_columnCount_7\":\"dm-grid-view_columnCount_7\",\"grid-view_columnCount_8\":\"dm-grid-view_columnCount_8\",\"grid-view_columnCount_9\":\"dm-grid-view_columnCount_9\",\"grid-view_columnCount_10\":\"dm-grid-view_columnCount_10\",\"grid-view_columnCount_11\":\"dm-grid-view_columnCount_11\",\"grid-view_columnCount_12\":\"dm-grid-view_columnCount_12\",\"grid-view_columnCount_13\":\"dm-grid-view_columnCount_13\",\"grid-view_columnCount_14\":\"dm-grid-view_columnCount_14\",\"grid-view__cell-header\":\"dm-grid-view__cell-header\",\"grid-view__cell-content\":\"dm-grid-view__cell-content\",\"grid-view__cell_selected\":\"dm-grid-view__cell_selected\",\"skeletonLoader\":\"dm-skeletonLoader\",\"grid-image-wrapper\":\"dm-grid-image-wrapper\"};","import { observer } from \"mobx-react\";\nimport React from \"react\";\nimport AutoSizer from \"react-virtualized-auto-sizer\";\nimport { FixedSizeGrid } from \"react-window\";\nimport InfiniteLoader from \"react-window-infinite-loader\";\nimport { Block, Elem } from \"../../../utils/bem\";\nimport { Checkbox } from \"../../Common/Checkbox/Checkbox\";\nimport { Space } from \"../../Common/Space/Space\";\nimport { getProperty, prepareColumns } from \"../../Common/Table/utils\";\nimport * as DataGroups from \"../../DataGroups\";\nimport \"./GridView.scss\";\nimport { FF_LOPS_E_3, isFF } from \"../../../utils/feature-flags\";\nimport { SkeletonLoader } from \"../../Common/SkeletonLoader\";\n\nconst GridHeader = observer(({ row, selected }) => {\n  return (\n    <Elem name=\"cell-header\">\n      <Space>\n        <Checkbox checked={selected.isSelected(row.id)} />\n        <span>{row.id}</span>\n      </Space>\n    </Elem>\n  );\n});\n\nexport const GridBody = observer(({ row, fields }) => {\n  const dataFields = fields.filter((f) => f.parent?.alias === \"data\");\n\n  return dataFields.map((field, index) => {\n    const valuePath = field.id.split(\":\")[1] ?? field.id;\n    const field_type = field.currentType;\n    let value = getProperty(row, valuePath);\n\n    /**The value is an array...\n     * In this case, we take the first element of the array\n     */\n    if (Array.isArray(value)) {\n      value = value[0];\n    }\n\n    return <GridDataGroup key={`${row.id}-${index}`} type={field_type} value={value} field={field} row={row} />;\n  });\n});\n\nconst GridDataGroup = observer(({ type, value, field, row }) => {\n  const DataTypeComponent = DataGroups[type];\n\n  return isFF(FF_LOPS_E_3) && row.loading === field.alias ? (\n    <SkeletonLoader />\n  ) : DataTypeComponent ? (\n    <DataTypeComponent value={value} field={field} original={row} />\n  ) : (\n    <DataGroups.TextDataGroup value={value} field={field} original={row} />\n  );\n});\n\nconst GridCell = observer(({ view, selected, row, fields, onClick, ...props }) => {\n  return (\n    <Elem {...props} name=\"cell\" onClick={onClick} mod={{ selected: selected.isSelected(row.id) }}>\n      <Elem name=\"cell-content\">\n        <GridHeader view={view} row={row} fields={fields} selected={view.selected} />\n        <GridBody view={view} row={row} fields={fields} />\n      </Elem>\n    </Elem>\n  );\n});\n\nexport const GridView = observer(({ data, view, loadMore, fields, onChange, hiddenFields }) => {\n  const columnCount = view.gridWidth ?? 4;\n\n  const getCellIndex = (row, column) => columnCount * row + column;\n\n  const fieldsData = React.useMemo(() => {\n    return prepareColumns(fields, hiddenFields);\n  }, [fields, hiddenFields]);\n\n  const rowHeight = fieldsData\n    .filter((f) => f.parent?.alias === \"data\")\n    .reduce((res, f) => {\n      const height = (DataGroups[f.currentType] ?? DataGroups.TextDataGroup).height;\n\n      return res + height;\n    }, 16);\n\n  const renderItem = React.useCallback(\n    ({ style, rowIndex, columnIndex }) => {\n      const index = getCellIndex(rowIndex, columnIndex);\n      const row = data[index];\n\n      if (!row) return null;\n\n      const props = {\n        style: {\n          ...style,\n          marginLeft: \"1em\",\n        },\n      };\n\n      return (\n        <GridCell\n          {...props}\n          view={view}\n          row={row}\n          fields={fieldsData}\n          selected={view.selected}\n          onClick={() => onChange?.(row.id)}\n        />\n      );\n    },\n    [data, fieldsData, view.selected, view, view.selected.list, view.selected.all, columnCount],\n  );\n\n  const onItemsRenderedWrap =\n    (cb) =>\n    ({ visibleRowStartIndex, visibleRowStopIndex, overscanRowStopIndex, overscanRowStartIndex }) => {\n      cb({\n        overscanStartIndex: overscanRowStartIndex,\n        overscanStopIndex: overscanRowStopIndex,\n        visibleStartIndex: visibleRowStartIndex,\n        visibleStopIndex: visibleRowStopIndex,\n      });\n    };\n\n  const itemCount = Math.ceil(data.length / columnCount);\n\n  const isItemLoaded = React.useCallback(\n    (index) => {\n      const rowIndex = index * columnCount;\n      const rowFullfilled = data.slice(rowIndex, columnCount).length === columnCount;\n\n      return !view.dataStore.hasNextPage || rowFullfilled;\n    },\n    [columnCount, data, view.dataStore.hasNextPage],\n  );\n\n  return (\n    <Block name=\"grid-view\" mod={{ columnCount }}>\n      <Elem tag={AutoSizer} name=\"resize\">\n        {({ width, height }) => (\n          <InfiniteLoader\n            itemCount={itemCount}\n            isItemLoaded={isItemLoaded}\n            loadMoreItems={loadMore}\n            threshold={Math.floor(view.dataStore.pageSize / 2)}\n            minimumBatchSize={view.dataStore.pageSize}\n          >\n            {({ onItemsRendered, ref }) => (\n              <Elem\n                tag={FixedSizeGrid}\n                ref={ref}\n                width={width}\n                height={height}\n                name=\"list\"\n                rowHeight={rowHeight + 42}\n                overscanRowCount={view.dataStore.pageSize}\n                columnCount={columnCount}\n                columnWidth={width / columnCount - 9.5}\n                rowCount={itemCount}\n                onItemsRendered={onItemsRenderedWrap(onItemsRendered)}\n                style={{ overflowX: \"hidden\" }}\n              >\n                {renderItem}\n              </Elem>\n            )}\n          </InfiniteLoader>\n        )}\n      </Elem>\n    </Block>\n  );\n});\n","import { inject } from \"mobx-react\";\nimport { getRoot } from \"mobx-state-tree\";\nimport { useCallback, useMemo } from \"react\";\nimport { FaQuestionCircle } from \"react-icons/fa\";\nimport { useShortcut } from \"../../../sdk/hotkeys\";\nimport { Block, Elem } from \"../../../utils/bem\";\nimport { FF_DEV_2536, FF_LOPS_86, FF_OPTIC_2, isFF } from \"../../../utils/feature-flags\";\nimport * as CellViews from \"../../CellViews\";\nimport { Icon } from \"../../Common/Icon/Icon\";\nimport { ImportButton } from \"../../Common/SDKButtons\";\nimport { Spinner } from \"../../Common/Spinner\";\nimport { Table } from \"../../Common/Table/Table\";\nimport { Tag } from \"../../Common/Tag/Tag\";\nimport { Tooltip } from \"../../Common/Tooltip/Tooltip\";\nimport { GridView } from \"../GridView/GridView\";\nimport \"./Table.scss\";\nimport { Button } from \"../../Common/Button/Button\";\nimport { useState } from \"react\";\nimport { useEffect } from \"react\";\n\nconst injector = inject(({ store }) => {\n  const { dataStore, currentView } = store;\n  const props = {\n    store,\n    dataStore,\n    updated: dataStore.updated,\n    view: currentView,\n    viewType: currentView?.type ?? \"list\",\n    columns: currentView?.fieldsAsColumns ?? [],\n    hiddenColumns: currentView?.hiddenColumnsList,\n    selectedItems: currentView?.selected,\n    selectedCount: currentView?.selected?.length ?? 0,\n    isLabeling: store.isLabeling ?? false,\n    data: dataStore?.list ?? [],\n    total: dataStore?.total ?? 0,\n    isLoading: dataStore?.loading ?? true,\n    isLocked: currentView?.locked ?? false,\n    hasData: (store.project?.task_count ?? store.project?.task_number ?? dataStore?.total ?? 0) > 0,\n    focusedItem: dataStore?.selected ?? dataStore?.highlighted,\n  };\n\n  return props;\n});\n\nexport const DataView = injector(\n  ({\n    store,\n    data,\n    columns,\n    view,\n    selectedItems,\n    dataStore,\n    viewType,\n    total,\n    isLoading,\n    isLabeling,\n    hiddenColumns = [],\n    hasData = false,\n    isLocked,\n    ...props\n  }) => {\n    const [datasetStatusID, setDatasetStatusID] = useState(store.SDK.dataset?.status?.id);\n    const focusedItem = useMemo(() => {\n      return props.focusedItem;\n    }, [props.focusedItem]);\n\n    const loadMore = useCallback(async () => {\n      if (!dataStore.hasNextPage || dataStore.loading) return Promise.resolve();\n\n      await dataStore.fetch({ interaction: \"scroll\" });\n      return Promise.resolve();\n    }, [dataStore]);\n\n    const isItemLoaded = useCallback(\n      (data, index) => {\n        const rowExists = index < data.length && !!data[index];\n        const hasNextPage = dataStore.hasNextPage;\n\n        return !hasNextPage || rowExists;\n      },\n      [dataStore.hasNextPage],\n    );\n\n    const columnHeaderExtra = useCallback(({ parent, original, help }, decoration) => {\n      const children = [];\n\n      if (parent) {\n        children.push(\n          <Tag\n            key=\"column-type\"\n            color=\"blue\"\n            style={{ fontWeight: \"500\", fontSize: 14, cursor: \"pointer\", width: 45, padding: 0 }}\n          >\n            {original?.readableType ?? parent.title}\n          </Tag>,\n        );\n      }\n\n      if (help && decoration?.help !== false) {\n        children.push(\n          <Tooltip key=\"help-tooltip\" title={help}>\n            <Icon icon={FaQuestionCircle} style={{ opacity: 0.5 }} />\n          </Tooltip>,\n        );\n      }\n\n      return children.length ? <>{children}</> : null;\n    }, []);\n\n    const onSelectAll = useCallback(() => view.selectAll(), [view]);\n\n    const onRowSelect = useCallback((id) => view.toggleSelected(id), [view]);\n\n    const onRowClick = useCallback(\n      async (item, e) => {\n        const itemID = item.task_id ?? item.id;\n\n        if (store.SDK.type === \"DE\") {\n          store.SDK.invoke(\"recordPreview\", item, columns, getRoot(view).taskStore.associatedList);\n        } else if (e.metaKey || e.ctrlKey) {\n          window.open(`./?task=${itemID}`, \"_blank\");\n        } else {\n          if (isFF(FF_OPTIC_2)) store._sdk.lsf?.saveDraft();\n          getRoot(view).startLabeling(item);\n        }\n      },\n      [view, columns],\n    );\n\n    const renderContent = useCallback(\n      (content) => {\n        if (isLoading && total === 0 && !isLabeling) {\n          return (\n            <Block name=\"fill-container\">\n              <Spinner size=\"large\" />\n            </Block>\n          );\n        }\n        if (store.SDK.type === \"DE\" && [\"canceled\", \"failed\"].includes(datasetStatusID)) {\n          return (\n            <Block name=\"syncInProgress\">\n              <Elem name=\"title\" tag=\"h3\">\n                Failed to sync data\n              </Elem>\n              {isFF(FF_LOPS_86) ? (\n                <>\n                  <Elem name=\"text\">Check your storage settings and resync to import records</Elem>\n                  <Button\n                    onClick={async () => {\n                      window.open(\"./settings/storage\");\n                    }}\n                  >\n                    Manage Storage\n                  </Button>\n                </>\n              ) : (\n                <Elem name=\"text\">Check your storage settings. You may need to recreate this dataset</Elem>\n              )}\n            </Block>\n          );\n        }\n        if (\n          store.SDK.type === \"DE\" &&\n          (total === 0 || data.length === 0 || !hasData) &&\n          datasetStatusID === \"completed\"\n        ) {\n          return (\n            <Block name=\"syncInProgress\">\n              <Elem name=\"title\" tag=\"h3\">\n                Nothing found\n              </Elem>\n              <Elem name=\"text\">Try adjusting the filter or similarity search parameters</Elem>\n            </Block>\n          );\n        }\n        if (store.SDK.type === \"DE\" && (total === 0 || data.length === 0 || !hasData)) {\n          return (\n            <Block name=\"syncInProgress\">\n              <Elem name=\"title\" tag=\"h3\">\n                Hang tight! Records are syncing in the background\n              </Elem>\n              <Elem name=\"text\">Press the button below to see any synced records</Elem>\n              <Button\n                onClick={async () => {\n                  await store.fetchProject({ force: true, interaction: \"refresh\" });\n                  await store.currentView?.reload();\n                }}\n              >\n                Refresh\n              </Button>\n            </Block>\n          );\n        }\n        if (total === 0 || !hasData) {\n          return (\n            <Block name=\"no-results\">\n              <Elem name=\"description\">\n                {hasData ? (\n                  <>\n                    <h3>Nothing found</h3>\n                    Try adjusting the filter\n                  </>\n                ) : (\n                  \"Looks like you have not imported any data yet\"\n                )}\n              </Elem>\n              {!hasData && !!store.interfaces.get(\"import\") && (\n                <Elem name=\"navigation\">\n                  <ImportButton look=\"primary\" href=\"./import\">\n                    Go to import\n                  </ImportButton>\n                </Elem>\n              )}\n            </Block>\n          );\n        }\n\n        return content;\n      },\n      [hasData, isLabeling, isLoading, total, datasetStatusID],\n    );\n\n    const decorationContent = (col) => {\n      const column = col.original;\n\n      if (column.icon) {\n        return <Tooltip title={column.help ?? col.title}>{column.icon}</Tooltip>;\n      }\n\n      return column.title;\n    };\n\n    const commonDecoration = useCallback(\n      (alias, size, align = \"flex-start\", help = false) => ({\n        alias,\n        content: decorationContent,\n        style: (col) => ({ width: col.width ?? size, justifyContent: align }),\n        help,\n      }),\n      [],\n    );\n\n    const decoration = useMemo(\n      () => [\n        commonDecoration(\"total_annotations\", 60, \"center\"),\n        commonDecoration(\"cancelled_annotations\", 60, \"center\"),\n        commonDecoration(\"total_predictions\", 60, \"center\"),\n        commonDecoration(\"completed_at\", 180, \"space-between\", true),\n        commonDecoration(\"reviews_accepted\", 60, \"center\"),\n        commonDecoration(\"reviews_rejected\", 60, \"center\"),\n        commonDecoration(\"ground_truth\", 60, \"center\"),\n        isFF(FF_DEV_2536) && commonDecoration(\"comment_count\", 60, \"center\"),\n        isFF(FF_DEV_2536) && commonDecoration(\"unresolved_comment_count\", 60, \"center\"),\n        {\n          resolver: (col) => col.type === \"Number\",\n          style(col) {\n            return /id/.test(col.id) ? { width: 50 } : { width: 110 };\n          },\n        },\n        {\n          resolver: (col) => col.type === \"Image\" && col.original && getRoot(col.original)?.SDK?.type !== \"DE\",\n          style: { width: 150, justifyContent: \"center\" },\n        },\n        {\n          resolver: (col) => col.type === \"Image\" && col.original && getRoot(col.original)?.SDK?.type === \"DE\",\n          style: { width: 150 },\n        },\n        {\n          resolver: (col) => [\"Date\", \"Datetime\"].includes(col.type),\n          style: { width: 240 },\n        },\n        {\n          resolver: (col) => [\"Audio\", \"AudioPlus\"].includes(col.type),\n          style: { width: 150 },\n        },\n      ],\n      [commonDecoration],\n    );\n\n    const content =\n      view.root.isLabeling || viewType === \"list\" ? (\n        <Table\n          view={view}\n          data={data}\n          rowHeight={70}\n          total={total}\n          loadMore={loadMore}\n          fitContent={isLabeling}\n          columns={columns}\n          hiddenColumns={hiddenColumns}\n          cellViews={CellViews}\n          decoration={decoration}\n          order={view.ordering}\n          focusedItem={focusedItem}\n          isItemLoaded={isItemLoaded}\n          sortingEnabled={view.type === \"list\"}\n          columnHeaderExtra={columnHeaderExtra}\n          selectedItems={selectedItems}\n          onSelectAll={onSelectAll}\n          onSelectRow={onRowSelect}\n          onRowClick={onRowClick}\n          stopInteractions={isLocked}\n          onTypeChange={(col, type) => col.original.setType(type)}\n          onColumnResize={(col, width) => {\n            col.original.setWidth(width);\n          }}\n          onColumnReset={(col) => {\n            col.original.resetWidth();\n          }}\n        />\n      ) : (\n        <GridView\n          view={view}\n          data={data}\n          fields={columns}\n          loadMore={loadMore}\n          onChange={(id) => view.toggleSelected(id)}\n          hiddenFields={hiddenColumns}\n          stopInteractions={isLocked}\n        />\n      );\n\n    useShortcut(\"dm.focus-previous\", () => {\n      if (document.activeElement !== document.body) return;\n\n      const task = dataStore.focusPrev();\n\n      getRoot(view).startLabeling(task);\n    });\n\n    useShortcut(\"dm.focus-next\", () => {\n      if (document.activeElement !== document.body) return;\n\n      const task = dataStore.focusNext();\n\n      getRoot(view).startLabeling(task);\n    });\n\n    useShortcut(\"dm.close-labeling\", () => {\n      if (document.activeElement !== document.body) return;\n\n      if (dataStore.selected) store.closeLabeling();\n    });\n\n    useShortcut(\"dm.open-labeling\", () => {\n      if (document.activeElement !== document.body) return;\n\n      const { highlighted } = dataStore;\n      // don't close QuickView by Enter\n\n      if (highlighted && !highlighted.isSelected) store.startLabeling(highlighted);\n    });\n\n    useEffect(() => {\n      const updateDatasetStatus = (dataset) => dataset?.status?.id && setDatasetStatusID(dataset?.status?.id);\n\n      getRoot(store).SDK.on(\"datasetUpdated\", updateDatasetStatus);\n      return () => getRoot(store).SDK.off(\"datasetUpdated\", updateDatasetStatus);\n    }, []);\n\n    // Render the UI for your table\n    return (\n      <Block name=\"data-view\" className=\"dm-content\" style={{ pointerEvents: isLocked ? \"none\" : \"auto\" }}>\n        {renderContent(content)}\n      </Block>\n    );\n  },\n);\n","import { inject, observer } from \"mobx-react\";\nimport React from \"react\";\nimport { Block } from \"../../../utils/bem\";\nimport { FF_LOPS_E_10, isFF } from \"../../../utils/feature-flags\";\nimport { Space } from \"../../Common/Space/Space\";\nimport \"./TabPanel.scss\";\n\nconst injector = inject(({ store }) => {\n  return {\n    store,\n  };\n});\n\nexport const Toolbar = injector(\n  observer(({ store }) => {\n    const isNewUI = isFF(FF_LOPS_E_10);\n\n    return (\n      <Block name=\"tab-panel\" mod={{ newUI: isNewUI }}>\n        {store.SDK.toolbarInstruments.map((section, i) => {\n          return (\n            <Space size=\"small\" key={`section-${i}`}>\n              {section.map((instrument, i) => {\n                const Instrument = store.SDK.getInstrument(instrument);\n\n                return Instrument ? (\n                  <Instrument key={`instrument-${instrument}-${i}`} size={isNewUI ? \"large\" : \"medium\"} />\n                ) : null;\n              })}\n            </Space>\n          );\n        })}\n      </Block>\n    );\n  }),\n);\n","import { inject, observer } from \"mobx-react\";\nimport React, { useCallback } from \"react\";\nimport { Draggable } from \"react-beautiful-dnd\";\nimport { LSPlus } from \"../../assets/icons\";\nimport { Block, Elem } from \"../../utils/bem\";\nimport { Interface } from \"../Common/Interface\";\nimport { Space } from \"../Common/Space/Space\";\nimport { Spinner } from \"../Common/Spinner\";\nimport { Tabs, TabsItem } from \"../Common/Tabs/Tabs\";\nimport { FiltersSidebar } from \"../Filters/FiltersSidebar/FilterSidebar\";\nimport { DataView } from \"../MainView\";\nimport \"./DataManager.scss\";\nimport { Toolbar } from \"./Toolbar/Toolbar\";\n\nconst injector = inject(({ store }) => {\n  const { sidebarEnabled, sidebarVisible } = store.viewsStore ?? {};\n\n  return {\n    shrinkWidth: sidebarEnabled && sidebarVisible,\n  };\n});\n\nconst summaryInjector = inject(({ store }) => {\n  const { project, taskStore } = store;\n\n  return {\n    totalTasks: project?.task_count ?? project?.task_number ?? 0,\n    totalFoundTasks: taskStore?.total ?? 0,\n    totalAnnotations: taskStore?.totalAnnotations ?? 0,\n    totalPredictions: taskStore?.totalPredictions ?? 0,\n    cloudSync: project.target_syncing ?? project.source_syncing ?? false,\n  };\n});\n\nconst switchInjector = inject(({ store }) => {\n  return {\n    sdk: store.SDK,\n    views: store.viewsStore,\n    tabs: Array.from(store.viewsStore?.all ?? []),\n    selectedKey: store.viewsStore?.selected?.key,\n  };\n});\n\nconst ProjectSummary = summaryInjector((props) => {\n  return (\n    <Space size=\"large\" style={{ paddingRight: \"1em\", color: \"rgba(0,0,0,0.3)\" }}>\n      {props.cloudSync && (\n        <Space size=\"small\" style={{ fontSize: 12, fontWeight: 400, opacity: 0.8 }}>\n          Storage sync\n          <Spinner size=\"small\" />\n        </Space>\n      )}\n      <span style={{ display: \"flex\", alignItems: \"center\", fontSize: 12 }}>\n        <Space size=\"compact\">\n          <span>\n            Tasks: {props.totalFoundTasks} / {props.totalTasks}\n          </span>\n          <span>Annotations: {props.totalAnnotations}</span>\n          <span>Predictions: {props.totalPredictions}</span>\n        </Space>\n      </span>\n    </Space>\n  );\n});\n\nconst TabsSwitch = switchInjector(\n  observer(({ sdk, views, tabs, selectedKey }) => {\n    const editable = sdk.tabControls;\n\n    const onDragEnd = useCallback((result) => {\n      if (!result.destination) {\n        return;\n      }\n\n      views.updateViewOrder(result.source.index, result.destination.index);\n    }, []);\n\n    return (\n      <Tabs\n        activeTab={selectedKey}\n        onAdd={() => views.addView({ reload: false })}\n        onChange={(key) => views.setSelected(key)}\n        onDragEnd={onDragEnd}\n        tabBarExtraContent={<ProjectSummary />}\n        addIcon={<LSPlus />}\n        allowedActions={editable}\n      >\n        {tabs.map((tab, index) => (\n          <Draggable key={tab.key} draggableId={tab.key} index={index}>\n            {(provided, snapshot) => (\n              <Elem\n                name={\"draggable\"}\n                ref={provided.innerRef}\n                {...provided.draggableProps}\n                {...provided.dragHandleProps}\n                style={{\n                  background: snapshot.isDragging && \"#ddd\",\n                  ...provided.draggableProps.style,\n                }}\n              >\n                <TabsItem\n                  key={tab.key}\n                  tab={tab.key}\n                  title={tab.title}\n                  onFinishEditing={(title) => {\n                    tab.setTitle(title);\n                    tab.save();\n                  }}\n                  onDuplicate={() => views.duplicateView(tab)}\n                  onClose={() => views.deleteView(tab)}\n                  onSave={() => tab.virtual && tab.saveVirtual()}\n                  active={tab.key === selectedKey}\n                  editable={tab.editable}\n                  deletable={tab.deletable}\n                  virtual={tab.virtual}\n                />\n              </Elem>\n            )}\n          </Draggable>\n        ))}\n      </Tabs>\n    );\n  }),\n);\n\nexport const DataManager = injector(({ shrinkWidth }) => {\n  return (\n    <Block name=\"tabs-content\">\n      <Elem name=\"tab\" mod={{ shrink: shrinkWidth }}>\n        <Interface name=\"tabs\">\n          <TabsSwitch />\n        </Interface>\n\n        <Interface name=\"toolbar\">\n          <Toolbar />\n        </Interface>\n\n        <DataView />\n      </Elem>\n      <FiltersSidebar />\n    </Block>\n  );\n});\n","import { inject } from \"mobx-react\";\nimport { observer } from \"mobx-react-lite\";\nimport React, { useCallback, useEffect, useMemo, useRef } from \"react\";\nimport { FaCaretDown, FaChevronLeft, FaColumns } from \"react-icons/fa\";\nimport { Block, Elem } from \"../../utils/bem\";\nimport { FF_DEV_1170, isFF } from \"../../utils/feature-flags\";\nimport { Button } from \"../Common/Button/Button\";\nimport { FieldsButton } from \"../Common/FieldsButton\";\nimport { Icon } from \"../Common/Icon/Icon\";\nimport { Resizer } from \"../Common/Resizer/Resizer\";\nimport { Space } from \"../Common/Space/Space\";\nimport { DataView } from \"../MainView\";\nimport \"./Label.scss\";\n\nconst LabelingHeader = ({ SDK, onClick, isExplorerMode }) => {\n  return (\n    <Elem name=\"header\" mod={{ labelStream: !isExplorerMode }}>\n      <Space size=\"large\">\n        {SDK.interfaceEnabled(\"backButton\") && (\n          <Button\n            icon={<FaChevronLeft style={{ marginRight: 4, fontSize: 16 }} />}\n            type=\"link\"\n            onClick={onClick}\n            style={{ fontSize: 18, padding: 0, color: \"black\" }}\n          >\n            Back\n          </Button>\n        )}\n\n        {isExplorerMode ? (\n          <FieldsButton\n            wrapper={FieldsButton.Checkbox}\n            icon={<Icon icon={FaColu