dataview\"\n                minWidth={200}\n                showResizerLine={false}\n                type={\"quickview\"}\n                maxWidth={window.innerWidth * 0.35}\n                initialWidth={view.labelingTableWidth} // hardcoded as in main-menu-trigger\n                onResizeFinished={onResize}\n                style={{ display: \"flex\", flex: 1, width: \"100%\" }}\n              >\n                <DataView />\n              </Elem>\n            </Elem>\n          )}\n\n          <Elem name=\"lsf-wrapper\" mod={{ mode: isExplorerMode ? \"explorer\" : \"labeling\" }}>\n            {loading && <Elem name=\"waiting\" mod={{ animated: true }} />}\n            <Elem\n              ref={lsfRef}\n              id=\"label-studio-dm\"\n              name=\"lsf-container\"\n              key=\"label-studio\"\n              mod={{ outliner: outlinerEnabled }}\n            />\n          </Elem>\n        </Elem>\n      </Block>\n    );\n  }),\n);\n","import { observer, Provider } from \"mobx-react\";\nimport React from \"react\";\nimport { SDKProvider } from \"../../providers/SDKProvider\";\nimport { Block, Elem } from \"../../utils/bem\";\nimport { Spinner } from \"../Common/Spinner\";\nimport { DataManager } from \"../DataManager/DataManager\";\nimport { Labeling } from \"../Label/Label\";\nimport \"./App.scss\";\n\nclass ErrorBoundary extends React.Component {\n  state = {\n    error: null,\n  };\n\n  componentDidCatch(error) {\n    this.setState({ error });\n  }\n\n  render() {\n    return this.state.error ? <div className=\"error\">{this.state.error}</div> : this.props.children;\n  }\n}\n\n/**\n * Main Component\n * @param {{app: import(\"../../stores/AppStore\").AppStore} param0\n */\nconst AppComponent = ({ app }) => {\n  return (\n    <ErrorBoundary>\n      <Provider store={app}>\n        <SDKProvider sdk={app.SDK}>\n          <Block name=\"root\" mod={{ mode: app.SDK.mode }}>\n            {app.crashed ? (\n              <Block name=\"crash\">\n                <Elem name=\"header\">Oops...</Elem>\n                <Elem name=\"description\">Project has been deleted or not yet created.</Elem>\n              </Block>\n            ) : app.loading ? (\n              <Block name=\"app-loader\">\n                <Spinner size=\"large\" />\n              </Block>\n            ) : app.isLabeling ? (\n              <Labeling />\n            ) : (\n              <DataManager />\n            )}\n            <Block name={\"offscreen-lsf\"} />\n          </Block>\n        </SDKProvider>\n      </Provider>\n    </ErrorBoundary>\n  );\n};\n\nexport const App = observer(AppComponent);\n","import { isDefined } from \"./utils\";\n\nexport const History = {\n  getParams(urlInstance) {\n    const url = urlInstance ?? new URL(window.location.href);\n    const result = {};\n\n    url.searchParams.forEach((value, key) => {\n      result[key] = value;\n    });\n\n    return result;\n  },\n\n  setParams(params = {}) {\n    const url = new URL(window.location.href);\n    const { searchParams } = url;\n\n    Object.entries(params).forEach(([key, value]) => {\n      if (value === null || value === undefined) {\n        searchParams.delete(key);\n      } else {\n        searchParams.set(key, value);\n      }\n    });\n\n    return url;\n  },\n\n  navigate(params = {}, replace = false) {\n    const url = this.setParams(params);\n    const title = document.title;\n    const state = this.getParams(url);\n\n    if (replace) {\n      window.history.replaceState(state, title, url.toString());\n    } else {\n      window.history.pushState(state, title, url.toString());\n    }\n  },\n\n  forceNavigate(params = {}, replace = false) {\n    const resultParams = params ?? {};\n    const currentParams = this.getParams();\n\n    Object.entries(currentParams).forEach(([key]) => {\n      if (!isDefined(resultParams[key])) {\n        resultParams[key] = null;\n      }\n    });\n\n    if (currentParams.query) {\n      resultParams.query = currentParams.query;\