n          console.warn(\"Columns\", columns);\n        }\n\n        const columnPath = result.join(\".\");\n\n        return { parentPath, columnPath };\n      };\n\n      targets.forEach((target) => {\n        self.columnsTargetMap.set(target, []);\n      });\n\n      columns.forEach((col) => {\n        if (!isDefined(col)) return;\n        const { columnPath, parentPath } = createColumnPath(columns, col);\n\n        const { target, visibility_defaults: visibility } = col;\n\n        const columnID = `${target}:${columnPath}`;\n\n        if (addedColumns.has(columnID)) return;\n\n        const parent = parentPath ? `${target}:${parentPath}` : undefined;\n\n        const children = col.children ? col.children.map((ch) => `${target}:${columnPath}.${ch}`) : undefined;\n\n        const colsList = self.columnsTargetMap.get(col.target);\n\n        colsList.push({\n          ...col,\n          id: columnID,\n          alias: col.id,\n          parent,\n          children,\n        });\n\n        const column = colsList[colsList.length - 1];\n\n        addedColumns.add(column.id);\n\n        if (!col.children && column.filterable && (col?.visibility_defaults?.filter ?? true)) {\n          self.availableFilters.push({\n            id: `filter:${columnID}`,\n            type: col.type,\n            field: columnID,\n            schema: col.schema ?? null,\n          });\n        }\n\n        Object.entries(visibility ?? {}).forEach(([key, visible]) => {\n          if (!visible) {\n            hiddenColumns[key] = hiddenColumns[key] ?? [];\n            hiddenColumns[key].push(column.id);\n          }\n        });\n      });\n\n      self.defaultHidden = TabHiddenColumns.create(hiddenColumns);\n    },\n\n    fetchTabs: flow(function* (tab, taskID, labeling) {\n      const tabId = Number.parseInt(tab);\n      const response = yield getRoot(self).apiCall(\"tabs\");\n      const tabs = response.tabs ?? response ?? [];\n      const columnIds = self.columns.map((c) => c.id);\n\n      const snapshots = tabs.map((t) => {\n        const { data, ...tab } = dataCleanup(t, columnIds);\n\n        return {\n          ...tab,\n          ...(data ?? {}),\n          saved: true,\n          hasData: !!data,\n        };\n      });\n\n      self.views.push(...snapshots);\n\n      yield self.setSelected(Number.isNaN(tabId) ? tab : tabId, {\n        pushState: tab === undefined,\n      });\n\n      yield self.selected?.save();\n\n      if (labeling) {\n        getRoot(self).startLabelStream({\n          pushState: false,\n        });\n      } else if (isDefined(taskID)) {\n        const task = { id: Number.parseInt(taskID) };\n\n        getRoot(self).startLabeling(task, {\n          pushState: false,\n        });\n      }\n    }),\n\n    fetchSingleTab: flow(function* (tabKey, selectedItems) {\n      let tab;\n      const tabId = Number.parseInt(tabKey);\n\n      if (!isNaN(tabKey) && !isNaN(tabId)) {\n        const tabData = yield getRoot(self).apiCall(\"tab\", { tabId });\n        const columnIds = (self.columns ?? []).map((c) => c.id);\n        const { data, ...tabClean } = dataCleanup(tabData, columnIds);\n\n        self.views.push({\n          ...tabClean,\n          ...(data ?? {}),\n          selected: {\n            all: selectedItems?.all,\n            list: selectedItems.included ?? selectedItems.excluded ?? [],\n          },\n          saved: true,\n          hasData: !!data,\n        });\n        tab = self.views[self.views.length - 1];\n      } else {\n        tab = yield self.getViewByKey(tabKey);\n      }\n\n      self.selected = tab;\n    }),\n  }));\n","export class ActivityObserver {\n  active = window.navigator.onLine && !document.hidden;\n\n  constructor() {\n    window.addEventListener(\"online\", this.handler);\n    window.addEventListener(\"offline\", this.handler);\n    document.addEventListener(\"visibilitychange\", this.handler);\n  }\n\n  destroy() {\n    window.removeEventListener(\"online\", this.handler);\n    window.removeEventListener(\"offline\", this.handler);\n    document.removeEventListener(\"visibilitychange\", this.handler);\n  }\n\n  private handler = () => {\n    this.active = window.navigator.onLine && !document.hidden;\n  };\n}\n","import { destroy, flow, types } from \"mobx-state-tree\";\nimport { Modal } from \"../components/Common/Modal/Modal\";\nimport { FF_DEV_2887, FF_LOPS_E_3, isFF } from \"../utils/feature-flags\";\nimport { History } from \"../utils/history\";\nimport { isDefined } from \"../utils/utils\";\nimport { Action } from \"./Action\";\nimport * as DataStores from \"./DataStores\";\nimport { DynamicModel, registerModel } from \"./DynamicModel\";\nimport { TabStore } from \"./Tabs\";\nimport { CustomJSON } from \"./types\";\nimport { User } from \"./Users\";\nimport { ActivityObserver } from \"../utils/ActivityObserver\";\n\n/**\n * @type {ActivityObserver | null}\n */\nlet networkActivity = null;\n\nconst PROJECTS_FETCH_PERIOD = 10 * 1000; // 10 seconds\n\nexport const AppStore = types\n  .model(\"AppStore\", {\n    mode: types.optional(types.enumeration([\"explorer\", \"labelstream\", \"labeling\"]), \"explorer\"),\n\n    viewsStore: types.optional(TabStore, {\n      views: [],\n    }),\n\n    project: types.optional(CustomJSON, {}),\n\n    loading: types.optional(types.boolean, false),\n\n    loadingData: false,\n\n    users: types.optional(types.array(User), []),\n\n    taskStore: types.optional(\n      types.late(() => {\n        return DynamicModel.get(\"tasksStore\");\n      }),\n      {},\n    ),\n\n    annotationStore: types.optional(\n      types.late(() => {\n        return DynamicModel.get(\"annotationsStore\");\n      }),\n      {},\n    ),\n\n    availableActions: types.optional(types.array(Action), []),\n\n    serverError: types.map(CustomJSON),\n\n    crashed: false,\n\n    interfaces: types.map(types.boolean),\n\n    toolbar: types.string,\n  })\n  .views((self) => ({\n    /** @returns {import(\"../sdk/dm-sdk\").DataManager} */\n    get SDK() {\n      return self._sdk;\n    },\n\n    /** @returns {import(\"../sdk/lsf-sdk\").LSFWrapper} */\n    get LSF() {\n      return self.SDK.lsf;\n    },\n\n    /** @returns {import(\"../utils/api-proxy\").APIProxy} */\n    get API() {\n      return self.SDK.api;\n    },\n\n    get apiVersion() {\n      return self.SDK.apiVersion;\n    },\n\n    get isLabeling() {\n      return !!self.dataStore?.selected || self.isLabelStreamMode || self.mode === \"labeling\";\n    },\n\n    get isLabelStreamMode() {\n      return self.mode === \"labelstream\";\n    },\n\n    get isExplorerMode() {\n      return self.mode === \"explorer\" || self.mode === \"labeling\";\n    },\n\n    get currentView() {\n      return self.viewsStore.selected;\n    },\n\n    get dataStore() {\n      switch (self.target) {\n        case \"tasks\":\n          return self.taskStore;\n        case \"annotations\":\n          return self.annotationStore;\n        default:\n          return null;\n      }\n    },\n\n    get target() {\n      return self.viewsStore.selected?.target ?? \"tasks\";\n    },\n\n    get labelingIsConfigured() {\n      return self.project?.config_has_control_tags === true;\n    },\n\n    get labelingConfig() {\n      return self.project.label_config_line ?? self.project.label_config;\n    },\n\n    get showPreviews() {\n      return self.SDK.showPreviews;\n    },\n\n    get currentSelection() {\n      return self.currentView.selected.snapshot;\n    },\n\n    get currentFilter() {\n      return self.currentView.filterSnposhot;\n    },\n  }))\n  .volatile(() => ({\n    needsDataFetch: false,\n    projectFetch: false,\n    requestsInFlight: new Map(),\n  }))\n  .actions((self) => ({\n    startPolling() {\n      if (self._poll) return;\n      if (self.SDK.polling === false) return;\n\n      const poll = async (self) => {\n        if (networkActivity.active) await self.fetchProject({ interaction: \"timer\" });\n        self._poll = setTimeout(() => poll(self), PROJECTS_FETCH_PERIOD);\n      };\n\n      poll(self);\n    },\n\n    afterCreate() {\n      networkActivity?.destroy();\n      networkActivity = new ActivityObserver();\n    },\n\n    beforeDestroy() {\n      clearTimeout(self._poll);\n      window.removeEventListener(\"popstate\", self.handlePopState);\n      networkActivity.destroy();\n    },\n\n    setMode(mode) {\n      self.mode = mode;\n    },\n\n    setActions(actions) {\n      if (!Array.isArray(actions)) throw new Error(\"Actions must be an array\");\n      self.availableActions = actions;\n    },\n\n    removeAction(id) {\n      const action = self.availableActions.find((action) => action.id === id);\n\n      if (action) destroy(action);\n    },\n\n    interfaceEnabled(name) {\n      return self.interfaces.get(name) === true;\n    },\n\n    enableInterface(name) {\n      if (!self.interfaces.has(name)) {\n        console.warn(`Unknown interface ${name}`);\n      } else {\n        self.interfaces.set(name, true);\n      }\n    },\n\n    disableInterface(name) {\n      if (!self.interfaces.has(name)) {\n        console.warn(`Unknown interface ${name}`);\n      } else {\n        self.interfaces.set(name, false);\n      }\n    },\n\n    setToolbar(toolbarString) {\n      self.toolbar = toolbarString;\n    },\n\n    setTask: flow(function* ({ taskID, annotationID, pushState }) {\n      if (pushState !== false) {\n        History.navigate({ task: taskID, annotation: annotationID ?? null, interaction: null });\n      }\n\n      if (!isDefined(taskID)) return;\n\n      self.loadingData = true;\n\n      if (self.mode === \"labelstream\") {\n        yield self.taskStore.loadNextTask({\n          select: !!taskID && !!annotationID,\n        });\n      }\n\n      if (annotationID !== undefined) {\n        self.annotationStore.setSelected(annotationID);\n      } else {\n        self.taskStore.setSelected(taskID);\n\n        yield self.taskStore.loadTask(taskID, {\n          select: !!taskID && !!annotationID,\n        });\n\n        const annotation = self.LSF?.currentAnnotation;\n        const id = annotation?.pk ?? annotation?.id;\n\n        self.LSF?.setLSFTask(self.taskStore.selected, id);\n\n        self.loadingData = false;\n      }\n    }),\n\n    unsetTask(options) {\n      try {\n        self.annotationStore.unset();\n        self.taskStore.unset();\n      } catch (e) {\n        /* Something weird */\n      }\n\n      if (options?.pushState !== false) {\n        History.navigate({ task: null, annotation: null });\n      }\n    },\n\n    unsetSelection() {\n      self.annotationStore.unset({ withHightlight: true });\n      self.taskStore.unset({ withHightlight: true });\n    },\n\n    createDataStores() {\n      const grouppedColumns = self.viewsStore.columns.reduce((res, column) => {\n        res.set(column.target, res.get(column.target) ?? []);\n        res.get(column.target).push(column);\n        return res;\n      }, new Map());\n\n      grouppedColumns.forEach((columns, target) => {\n        const dataStore = DataStores[target].create?.(columns);\n\n        if (dataStore) registerModel(`${target}Store`, dataStore);\n      });\n    },\n\n    startLabelStream(options = {}) {\n      if (!self.confirmLabelingConfigured()) return;\n\n      const nextAction = () => {\n        self.SDK.setMode(\"labelstream\");\n\n        if (options?.pushState !== false) {\n          History.navigate({ labeling: 1 });\n        }\n      };\n\n      if (isFF(FF_DEV_2887) && self.LSF?.lsf?.annotationStore?.selected?.commentStore?.hasUnsaved) {\n        Modal.confirm({\n          title: \"You have unsaved changes\",\n          body: \"There are comments which are not persisted. Please submit the annotation. Continuing will discard these comments.\",\n          onOk() {\n            nextAction();\n          },\n          okText: \"Discard and continue\",\n        });\n        return;\n      }\n\n      nextAction();\n    },\n\n    startLabeling(item, options = {}) {\n      if (!self.confirmLabelingConfigured()) return;\n\n      if (self.dataStore.loadingItem) return;\n\n      const nextAction = () => {\n        self.SDK.setMode(\"labeling\");\n\n        if (item && !item.isSelected) {\n          const labelingParams = {\n            pushState: options?.pushState,\n          };\n\n          if (isDefined(item.task_id)) {\n            Object.assign(labelingParams, {\n              annotationID: item.id,\n              taskID: item.task_id,\n            });\n          } else {\n            Object.assign(labelingParams, {\n              taskID: item.id,\n            });\n          }\n\n          self.setTask(labelingParams);\n        } else {\n          self.closeLabeling();\n        }\n      };\n\n      if (isFF(FF_DEV_2887) && self.LSF?.lsf?.annotationStore?.selected?.commentStore?.hasUnsaved) {\n        Modal.confirm({\n          title: \"You have unsaved changes\",\n          body: \"There are comments which are not persisted. Please submit the annotation. Continuing will discard these comments.\",\n          onOk() {\n            nextAction();\n          },\n          okText: \"Discard and continue\",\n        });\n        return;\n      }\n\n      nextAction();\n    },\n\n    confirmLabelingConfigured() {\n      if (!self.labelingIsConfigured) {\n        Modal.confirm({\n          title: \"You're almost there!\",\n          body: \"Before you can annotate the data, set up labeling configuration\",\n          onOk() {\n            self.SDK.invoke(\"settingsClicked\");\n          },\n          okText: \"Go to setup\",\n        });\n        return false;\n      }\n      return true;\n    },\n\n    closeLabeling(options) {\n      const { SDK } = self;\n\n      self.unsetTask(options);\n\n      let viewId;\n      const tabFromURL = History.getParams().tab;\n\n      if (isDefined(self.currentView)) {\n        viewId = self.currentView.tabKey;\n      } else if (isDefined(tabFromURL)) {\n        viewId = tabFromURL;\n      } else if (isDefined(self.viewsStore)) {\n        viewId = self.viewsStore.views[0]?.tabKey;\n      }\n\n      if (isDefined(viewId)) {\n        History.forceNavigate({ tab: viewId });\n      }\n\n      SDK.setMode(\"explorer\");\n      SDK.destroyLSF();\n    },\n\n    handlePopState: (({ state }) => {\n      const { tab, task, annotation, labeling } = state ?? {};\n\n      if (tab) {\n        const tabId = Number.parseInt(tab);\n\n        self.viewsStore.setSelected(Number.isNaN(tabId) ? tab : tabId, {\n          pushState: false,\n          createDefault: false,\n        });\n      }\n\n      if (task) {\n        const params = {};\n\n        if (annotation) {\n          params.task_id = Number.parseInt(task);\n          params.id = Number.parseInt(annotation);\n        } else {\n          params.id = Number.parseInt(task);\n        }\n\n        self.startLabeling(params, { pushState: false });\n      } else if (labeling) {\n        self.startLabelStream({ pushState: false });\n      } else {\n        self.closeLabeling({ pushState: false });\n      }\n    }).bind(self),\n\n    resolveURLParams() {\n      window.addEventListener(\"popstate\", self.handlePopState);\n    },\n\n    setLoading(value) {\n      self.loading = value;\n    },\n\n    fetchProject: flow(function* (options = {}) {\n      self.projectFetch = options.force === true;\n\n      const isTimer = options.interaction === \"timer\";\n      const params =\n        options && options.interaction\n          ? {\n              interaction: options.interaction,\n              ...(isTimer\n                ? {\n                    include: [\n                      \"task_count\",\n                      \"task_number\",\n                      \"annotation_count\",\n                      \"num_tasks_with_annotations\",\n                      \"queue_total\",\n                    ].join(\",\"),\n                  }\n                : null),\n            }\n          : null;\n\n      try {\n        const newProject = yield self.apiCall(\"project\", params);\n        const projectLength = Object.entries(self.project ?? {}).length;\n\n        self.needsDataFetch =\n          options.force !== true && projectLength > 0\n            ? self.project.task_count !== newProject.task_count ||\n              self.project.task_number !== newProject.task_number ||\n              self.project.annotation_count !== newProject.annotation_count ||\n              self.project.num_tasks_with_annotations !== newProject.num_tasks_with_annotations\n            : false;\n\n        if (options.interaction === \"timer\") {\n          self.project = Object.assign(self.project ?? {}, newProject);\n        } else if (JSON.stringify(newProject ?? {}) !== JSON.stringify(self.project ?? {})) {\n          self.project = newProject;\n        }\n        if (isFF(FF_LOPS_E_3)) {\n          const itemType = self.SDK.type === \"DE\" ? \"dataset\" : \"project\";\n\n          self.SDK.invoke(`${itemType}Updated`, self.project);\n        }\n      } catch {\n        self.crash();\n        return false;\n      }\n      self.projectFetch = false;\n      return true;\n    }),\n\n    fetchActions: flow(function* () {\n      const serverActions = yield self.apiCall(\"actions\");\n\n      const actions = (serverActions ?? []).map((action) => {\n        return [action, undefined];\n      });\n\n      self.SDK.updateActions(actions);\n    }),\n\n    fetchUsers: flow(function* () {\n      const list = yield self.apiCall(\"users\");\n\n      self.users.push(...list);\n    }),\n\n    fetchData: flow(function* ({ isLabelStream } = {}) {\n      self.setLoading(true);\n\n      const { tab, task, labeling, query } = History.getParams();\n\n      self.viewsStore.fetchColumns();\n\n      const requests = [self.fetchProject(), self.fetchUsers()];\n\n      if (!isLabelStream || (self.project?.show_annotation_history && task)) {\n        if (self.SDK.type === \"dm\") {\n          requests.push(self.fetchActions());\n        }\n\n        if (self.SDK.settings?.onlyVirtualTabs && self.project?.show_annotation_history && !task) {\n          requests.push(\n            self.viewsStore.addView(\n              {\n                virtual: true,\n                projectId: self.SDK.projectId,\n                tab,\n              },\n              { autosave: false, reload: false },\n            ),\n          );\n        } else if (self.SDK.type === \"labelops\") {\n          requests.push(\n            self.viewsStore.addView(\n              {\n                virtual: false,\n                projectId: self.SDK.projectId,\n                tab,\n              },\n              { autosave: false, autoSelect: true, reload: true },\n            ),\n          );\n        } else {\n          requests.push(self.viewsStore.fetchTabs(tab, task, labeling));\n        }\n      } else if (isLabelStream && !!tab) {\n        const { selectedItems } = JSON.parse(decodeURIComponent(query ?? \"{}\"));\n\n        requests.push(self.viewsStore.fetchSingleTab(tab, selectedItems ?? {}));\n      }\n\n      const [projectFetched] = yield Promise.all(requests);\n\n      if (projectFetched) {\n        self.resolveURLParams();\n\n        self.setLoading(false);\n\n        self.startPolling();\n      }\n    }),\n\n    /**\n     * Main API calls provider for the whole application.\n     * `params` are used both for var substitution and query params if var is unknown:\n     * `{ project: 123, order: \"desc\" }` for method `\"tasks\": \"/project/:pk/tasks\"`\n     * will produce `/project/123/tasks?order=desc` url\n     * @param {string} methodName one of the methods in api-config\n     * @param {object} params url vars and query string params\n     * @param {object} body for POST/PATCH requests\n     * @param {{ errorHandler?: fn, headers?: object, allowToCancel?: boolean }} [options] additional options like errorHandler\n     */\n    apiCall: flow(function* (methodName, params, body, options) {\n      const isAllowCancel = options?.allowToCancel;\n      const controller = new AbortController();\n      const signal = controller.signal;\n      const apiTransform = self.SDK.apiTransform?.[methodName];\n      const requestParams = apiTransform?.params?.(params) ?? params ?? {};\n      const requestBody = apiTransform?.body?.(body) ?? body ?? {};\n      const requestHeaders = apiTransform?.headers?.(options?.headers) ?? options?.headers ?? {};\n      const requestKey = `${methodName}_${JSON.stringify(params || {})}`;\n\n      if (isAllowCancel) {\n        requestHeaders.signal = signal;\n        if (self.requestsInFlight.has(requestKey)) {\n          /* if already in flight cancel the first in favor of new one */\n          self.requestsInFlight.get(requestKey).abort();\n          console.log(`Request ${requestKey} canceled`);\n        }\n        self.requestsInFlight.set(requestKey, controller);\n      }\n      const result = yield self.API[methodName](requestParams, {\n        headers: requestHeaders,\n        body: requestBody.body ?? requestBody,\n        options,\n      });\n\n      if (isAllowCancel) {\n        result.isCanceled = signal.aborted;\n        self.requestsInFlight.delete(requestKey);\n      }\n      if (result.error && result.status !== 404 && !signal.aborted) {\n        if (options?.errorHandler?.(result)) {\n          return result;\n        }\n\n        if (result.response) {\n          try {\n            self.serverError.set(methodName, {\n              error: \"Something went wrong\",\n              response: result.response,\n            });\n          } catch {\n            // ignore\n          }\n        }\n\n        console.warn({\n          message: \"Error occurred when loading data\",\n          description: result?.response?.detail ?? result.error,\n        });\n\n        self.SDK.invoke(\"error\", result);\n\n        // notification.error({\n        //   message: \"Error occurred when loading data\",\n        //   description: result?.response?.detail ?? result.error,\n        // });\n      } else {\n        try {\n          self.serverError.delete(methodName);\n        } catch {\n          // ignore\n        }\n      }\n\n      return result;\n    }),\n\n    invokeAction: flow(function* (actionId, options = {}) {\n      const view = self.currentView ?? {};\n\n      const needsLock = self.availableActions.findIndex((a) => a.id === actionId) >= 0;\n\n      const { selected } = view;\n      const actionCallback = self.SDK.getAction(actionId);\n\n      if (view && needsLock && !actionCallback) view.lock();\n\n      const labelStreamMode = localStorage.getItem(\"dm:labelstream:mode\");\n\n      // @todo this is dirty way to sync across nested apps\n      // don't apply filters for \"all\" on \"next_task\"\n      const actionParams = {\n        ordering: view.ordering,\n        selectedItems: selected?.snapshot ?? { all: false, included: [] },\n        filters: {\n          conjunction: view.conjunction ?? \"and\",\n          items: view.serializedFilters ?? [],\n        },\n      };\n\n      if (actionId === \"next_task\") {\n        if (labelStreamMode === \"all\") {\n          delete actionParams.filters;\n\n          if (actionParams.selectedItems.all === false && actionParams.selectedItems.included.length === 0) {\n            delete actionParams.selectedItems;\n            delete actionParams.ordering;\n          }\n        } else if (labelStreamMode === \"filtered\") {\n          delete actionParams.selectedItems;\n        }\n      }\n\n      if (actionCallback instanceof Function) {\n        return actionCallback(actionParams, view);\n      }\n\n      const requestParams = {\n        id: actionId,\n      };\n\n      if (isDefined(view.id) && !view?.virtual) {\n        requestParams.tabID = view.id;\n      }\n\n      if (options.body) {\n        Object.assign(actionParams, options.body);\n      }\n\n      const result = yield self.apiCall(\"invokeAction\", requestParams, {\n        body: actionParams,\n      });\n\n      if (result.reload) {\n        self.SDK.reload();\n        return;\n      }\n\n      if (options.reload !== false) {\n        yield view.reload();\n        self.fetchProject();\n        view.clearSelection();\n      }\n\n      view?.unlock?.();\n\n      return result;\n    }),\n\n    crash() {\n      self.destroy();\n      self.crashed = true;\n      self.SDK.invoke(\"crash\");\n    },\n\n    destroy() {\n      if (self.taskStore) {\n        self.taskStore?.clear();\n        self.taskStore = undefined;\n      }\n\n      if (self.annotationStore) {\n        self.annotationStore?.clear();\n        self.annotationStore = undefined;\n      }\n\n      clearTimeout(self._poll);\n    },\n  }));\n","/** @typedef {{\n * views?: any[]\n * }} AppOptions */\n\nimport React from \"react\";\nimport ReactDOM from \"react-dom\";\nimport { App } from \"../components/App/App\";\nimport { AppStore } from \"../stores/AppStore\";\nimport * as DataStores from \"../stores/DataStores\";\nimport { registerModel } from \"../stores/DynamicModel\";\n\nconst createDynamicModels = (columns) => {\n  const grouppedColumns = columns.reduce((res, column) => {\n    res.set(column.target, res.get(column.target) ?? []);\n    res.get(column.target).push(column);\n    return res;\n  }, new Map());\n\n  grouppedColumns.forEach((columns, target) => {\n    const dataStore = DataStores[target].create?.(columns);\n\n    if (dataStore) registerModel(`${target}Store`, dataStore);\n  });\n\n  if (columns.length === 0) {\n    registerModel(\"tasksStore\", DataStores.tasks?.create());\n  }\n\n  /** temporary solution until we'll have annotations */\n  registerModel(\"annotationsStore\", DataStores.annotations?.create());\n};\n\n/**\n * Create DM React app\n * @param {HTMLElement} rootNode\n * @param {import(\"./dm-sdk\").DataManager} datamanager\n * @returns {Promise<AppStore>}\n */\nexport const createApp = async (rootNode, datamanager) => {\n  const isLabelStream = datamanager.mode === \"labelstream\";\n\n  const response = await datamanager.api.columns();\n\n  if (!response || response.error) {\n    const message = `\n      ${response?.error ?? \"\"}\n      LS API not available; check \\`API_GATEWAY\\` and \\`LS_ACCESS_TOKEN\\` env vars;\n      also check \\`data-project-id\\` in \\`public/index.html\\`\n    `;\n\n    throw new Error(message);\n  }\n\n  const columns = response.columns ?? (Array.isArray(response) ? response : []);\n\n  createDynamicModels(columns);\n\n  const appStore = AppStore.create({\n    viewsStore: {\n      views: [],\n      columnsRaw: columns,\n    },\n    project: datamanager.project ?? {},\n    mode: datamanager.mode,\n    showPreviews: datamanager.showPreviews,\n    interfaces: Object.fromEntries(datamanager.interfaces),\n    toolbar: datamanager.toolbar,\n    availableActions: Array.from(datamanager.actions.values()).map(({ action }) => action),\n  });\n\n  appStore._sdk = datamanager;\n\n  appStore.fetchData({ isLabelStream });\n\n  window.DM = appStore;\n\n  ReactDOM.render(<App app={appStore} />, rootNode);\n\n  return appStore;\n};\n","import { FF_DEV_3034, isFF } from \"../utils/feature-flags\";\n\nexport class CommentsSdk {\n  constructor(lsf, dm) {\n    this.lsf = lsf;\n    this.dm = dm;\n    this.bindEventHandlers();\n  }\n\n  bindEventHandlers() {\n    [\"comments:create\", \"comments:update\", \"comments:delete\", \"comments:list\"].forEach((evt) => this.lsf.off(evt));\n\n    this.lsf.on(\"comments:create\", this.createComment);\n    this.lsf.on(\"comments:update\", this.updateComment);\n    this.lsf.on(\"comments:delete\", this.deleteComment);\n    this.lsf.on(\"comments:list\", this.listComments);\n  }\n\n  createComment = async (comment) => {\n    const body = {\n      is_resolved: comment.is_resolved,\n      text: comment.text,\n    };\n\n    if (comment.annotation) {\n      body.annotation = comment.annotation;\n    } else if (isFF(FF_DEV_3034) && comment.draft) {\n      body.draft = comment.draft;\n    }\n    const { $meta: _, ...newComment } = await this.dm.apiCall(\"createComment\", undefined, {\n      body,\n    });\n\n    return newComment;\n  };\n\n  updateComment = async (comment) => {\n    if (!comment.id || comment.id < 0) return; // Don't allow an update with an incorrect id\n\n    const res = await this.dm.apiCall(\"updateComment\", { id: comment.id }, { body: comment });\n\n    return res;\n  };\n\n  listComments = async (params) => {\n    const listParams = {\n      ordering: params.ordering || \"-id\",\n      expand_created_by: true,\n    };\n\n    if (params.annotation) {\n      listParams.annotation = params.annotation;\n    } else if (isFF(FF_DEV_3034) && params.draft) {\n      listParams.draft = params.draft;\n    } else {\n      return [];\n    }\n\n    const res = await this.dm.apiCall(\"listComments\", listParams);\n\n    const commentUsers = [];\n    const comments = res.map((comment) => {\n      commentUsers.push(comment.created_by);\n      return { ...comment, created_by: comment.created_by.id };\n    });\n\n    if (commentUsers.length) {\n      this.lsf.store.enrichUsers(commentUsers);\n    }\n\n    return comments;\n  };\n\n  deleteComment = async (comment) => {\n    if (!comment.id || comment.id < 0) return; // Don't allow an update with an incorrect id\n\n    const res = await this.dm.apiCall(\"deleteComment\", { id: comment.id }, { body: comment });\n\n    return res;\n  };\n}\n","/** @typedef {import(\"../stores/Tasks\").TaskModel} Task */\n/** @typedef {import(\"label-studio\").LabelStudio} LabelStudio */\n/** @typedef {import(\"./dm-sdk\").DataManager} DataManager */\n\n/** @typedef {{\n * user: Dict\n * config: string,\n * interfaces: string[],\n * task: Task\n * labelStream: boolean,\n * interfacesModifier: function,\n * messages: Dict<string|Function>\n * }} LSFOptions */\n\nimport {\n  FF_DEV_1752,\n  FF_DEV_2186,\n  FF_DEV_2887,\n  FF_DEV_3034,\n  FF_DEV_3734,\n  FF_LSDV_4620_3_ML,\n  FF_OPTIC_2,\n  isFF,\n} from \"../utils/feature-flags\";\nimport { isDefined } from \"../utils/utils\";\nimport { Modal } from \"../components/Common/Modal/Modal\";\nimport { CommentsSdk } from \"./comments-sdk\";\n// import { LSFHistory } from \"./lsf-history\";\nimport { annotationToServer, taskToLSFormat } from \"./lsf-utils\";\nimport { when } from \"mobx\";\n\nconst DEFAULT_INTERFACES = [\n  \"basic\",\n  \"controls\",\n  \"submit\",\n  \"update\",\n  \"predictions\",\n  \"topbar\",\n  \"predictions:menu\", // right menu with prediction items\n  \"annotations:menu\", // right menu with annotation items\n  \"annotations:current\",\n  \"side-column\", // entity\n  \"edit-history\", // undo/redo\n];\n\nlet LabelStudioDM;\n\nconst resolveLabelStudio = async () => {\n  if (LabelStudioDM) {\n    return LabelStudioDM;\n  }\n  if (window.LabelStudio) {\n    return (LabelStudioDM = window.LabelStudio);\n  }\n};\n\nexport class LSFWrapper {\n  /** @type {HTMLElement} */\n  root = null;\n\n  /** @type {DataManager} */\n  datamanager = null;\n\n  /** @type {Task} */\n  task = null;\n\n  /** @type {Annotation} */\n  initialAnnotation = null;\n\n  /** @type {LabelStudio} */\n  lsf = null;\n\n  /** @type {LSFHistory} */\n  // history = null;\n\n  /** @type {boolean} */\n  labelStream = false;\n\n  /** @type {boolean} */\n  isInteractivePreannotations = false;\n\n  /** @type {function} */\n  interfacesModifier = (interfaces) => interfaces;\n\n  /**\n   *\n   * @param {DataManager} dm\n   * @param {HTMLElement} element\n   * @param {LSFOptions} options\n   */\n  constructor(dm, element, options) {\n    this.datamanager = dm;\n    this.store = dm.store;\n    this.root = element;\n    this.task = options.task;\n    this.preload = options.preload;\n    this.labelStream = options.isLabelStream ?? false;\n    this.initialAnnotation = options.annotation;\n    this.interfacesModifier = options.interfacesModifier;\n    this.isInteractivePreannotations = options.isInteractivePreannotations ?? false;\n\n    let interfaces = [...DEFAULT_INTERFACES];\n\n    if (this.project.enable_empty_annotation === false) {\n      interfaces.push(\"annotations:deny-empty\");\n    }\n\n    if (this.labelStream) {\n      interfaces.push(\"infobar\");\n      interfaces.push(\"topbar:prevnext\");\n      if (FF_DEV_2186 && this.project.review_settings?.require_comment_on_reject) {\n        interfaces.push(\"comments:update\");\n      }\n      if (this.project.show_skip_button) {\n        interfaces.push(\"skip\");\n      }\n    } else {\n      interfaces.push(\n        \"infobar\",\n        \"annotations:add-new\",\n        \"annotations:view-all\",\n        \"annotations:delete\",\n        \"annotations:tabs\",\n        \"predictions:tabs\",\n      );\n    }\n\n    if (this.datamanager.hasInterface(\"instruction\")) {\n      interfaces.push(\"instruction\");\n    }\n\n    if (!this.labelStream && this.datamanager.hasInterface(\"groundTruth\")) {\n      interfaces.push(\"ground-truth\");\n    }\n\n    if (this.datamanager.hasInterface(\"autoAnnotation\")) {\n      interfaces.push(\"auto-annotation\");\n    }\n\n    if (isFF(FF_DEV_2887)) {\n      interfaces.push(\"annotations:comments\");\n      interfaces.push(\"comments:resolve-any\");\n    }\n\n    if (this.interfacesModifier) {\n      interfaces = this.interfacesModifier(interfaces, this.labelStream);\n    }\n\n    console.group(\"Interfaces\");\n    console.log([...interfaces]);\n\n    if (!this.shouldLoadNext()) {\n      interfaces = interfaces.filter((item) => {\n        return ![\"topbar:prevnext\", \"skip\"].includes(item);\n      });\n    }\n\n    console.log([...interfaces]);\n    console.groupEnd();\n    const queueTotal = dm.store.project.reviewer_queue_total || dm.store.project.queue_total;\n    const queueDone = dm.store.project.queue_done;\n    const queueLeft = dm.store.project.queue_left;\n    const queuePosition = queueDone ? queueDone + 1 : queueLeft ? queueTotal - queueLeft + 1 : 1;\n\n    const lsfProperties = {\n      user: options.user,\n      config: this.lsfConfig,\n      task: taskToLSFormat(this.task),\n      description: this.instruction,\n      interfaces,\n      users: dm.store.users.map((u) => u.toJSON()),\n      keymap: options.keymap,\n      forceAutoAnnotation: this.isInteractivePreannotations,\n      forceAutoAcceptSuggestions: this.isInteractivePreannotations,\n      messages: options.messages,\n      queueTotal,\n      queuePosition,\n\n      /* EVENTS */\n      onSubmitDraft: this.onSubmitDraft,\n      onLabelStudioLoad: this.onLabelStudioLoad,\n      onTaskLoad: this.onTaskLoad,\n      onPresignUrlForProject: this.onPresignUrlForProject,\n      onStorageInitialized: this.onStorageInitialized,\n      onSubmitAnnotation: this.onSubmitAnnotation,\n      onUpdateAnnotation: this.onUpdateAnnotation,\n      onDeleteAnnotation: this.onDeleteAnnotation,\n      onSkipTask: this.onSkipTask,\n      onUnskipTask: this.onUnskipTask,\n      onGroundTruth: this.onGroundTruth,\n      onEntityCreate: this.onEntityCreate,\n      onEntityDelete: this.onEntityDelete,\n      onSelectAnnotation: this.onSelectAnnotation,\n      onNextTask: this.onNextTask,\n      onPrevTask: this.onPrevTask,\n    };\n\n    this.initLabelStudio(lsfProperties);\n  }\n\n  /** @private */\n  async initLabelStudio(settings) {\n    try {\n      const LSF = await resolveLabelStudio();\n\n      this.lsfInstance = new LSF(this.root, settings);\n\n      this.lsfInstance.on(\"presignUrlForProject\", this.onPresignUrlForProject);\n\n      const names = Array.from(this.datamanager.callbacks.keys()).filter((k) => k.startsWith(\"lsf:\"));\n\n      names.forEach((name) => {\n        this.datamanager.getEventCallbacks(name).forEach((clb) => {\n          this.lsfInstance.on(name.replace(/^lsf:/, \"\"), clb);\n        });\n      });\n\n      if (isFF(FF_DEV_2887)) {\n        new CommentsSdk(this.lsfInstance, this.datamanager);\n      }\n\n      this.datamanager.invoke(\"lsfInit\", this, this.lsfInstance);\n    } catch (err) {\n      console.error(\"Failed to initialize LabelStudio\", settings);\n      console.error(err);\n    }\n  }\n\n  /** @private */\n  async preloadTask() {\n    const { comment: commentId, task: taskID } = this.preload;\n    const api = this.datamanager.api;\n    const params = { taskID };\n\n    if (commentId) {\n      params.with_comment = commentId;\n    }\n\n    if (params) {\n      const task = await api.call(\"task\", { params });\n      const noData = !task || (!task.annotations?.length && !task.drafts?.length);\n      const body = `Task #${taskID}${commentId ? ` with comment #${commentId}` : \"\"} was not found!`;\n\n      if (noData) {\n        Modal.modal({\n          title: \"Can't find task\",\n          body,\n        });\n        return false;\n      }\n\n      // for preload it's good to always load the first one\n      const annotation = task.annotations[0];\n\n      this.selectTask(task, annotation?.id, true);\n    }\n\n    return false;\n  }\n\n  /** @private */\n  async loadTask(taskID, annotationID, fromHistory = false) {\n    if (!this.lsf) {\n      return console.error(\"Make sure that LSF was properly initialized\");\n    }\n\n    const nextAction = async () => {\n      const tasks = this.datamanager.store.taskStore;\n\n      const newTask = await this.withinLoadingState(async () => {\n        let nextTask;\n\n        if (!isDefined(taskID)) {\n          nextTask = await tasks.loadNextTask();\n        } else {\n          nextTask = await tasks.loadTask(taskID);\n        }\n\n        /**\n         * If we're in label stream and there's no task – end the stream\n         * Otherwise allow user to continue exploring tasks after finished labelling\n         */\n        const noTask = this.labelStream && !nextTask;\n\n        this.lsf.setFlags({ noTask });\n\n        return nextTask;\n      });\n\n      // Add new data from received task\n      if (newTask) this.selectTask(newTask, annotationID, fromHistory);\n    };\n\n    if (isFF(FF_DEV_2887) && this.lsf?.commentStore?.hasUnsaved) {\n      Modal.confirm({\n        title: \"You have unsaved changes\",\n        body: \"There are comments which are not persisted. Please submit the annotation. Continuing will discard these comments.\",\n        onOk() {\n          nextAction();\n        },\n        okText: \"Discard and continue\",\n      });\n      return;\n    }\n\n    await nextAction();\n  }\n\n  exitStream() {\n    this.datamanager.invoke(\"navigate\", \"projects\");\n  }\n\n  selectTask(task, annotationID, fromHistory = false) {\n    const needsAnnotationsMerge = task && this.task?.id === task.id;\n    const annotations = needsAnnotationsMerge ? [...this.annotations] : [];\n\n    this.task = task;\n\n    if (needsAnnotationsMerge) {\n      this.task.mergeAnnotations(annotations);\n    }\n\n    this.loadUserLabels();\n\n    this.setLSFTask(task, annotationID, fromHistory);\n  }\n\n  setLSFTask(task, annotationID, fromHistory) {\n    if (!this.lsf) return;\n\n    const hasChangedTasks = this.lsf?.task?.id !== task?.id && task?.id;\n\n    this.setLoading(true, hasChangedTasks);\n    const lsfTask = taskToLSFormat(task);\n    const isRejectedQueue = isDefined(task.default_selected_annotation);\n    const taskList = this.datamanager.store.taskStore.list;\n    // annotations are set in LSF only and order in DM only, so combine them\n    const taskHistory = taskList\n      .map((task) => this.taskHistory.find((item) => item.taskId === task.id))\n      .filter(Boolean);\n\n    const extracted = taskHistory.find((item) => item.taskId === task.id);\n\n    if (!fromHistory && extracted) {\n      taskHistory.splice(taskHistory.indexOf(extracted), 1);\n      taskHistory.push(extracted);\n    }\n\n    if (!extracted) {\n      taskHistory.push({ taskId: task.id, annotationId: null });\n    }\n\n    if (isRejectedQueue && !annotationID) {\n      annotationID = task.default_selected_annotation;\n    }\n\n    if (hasChangedTasks) {\n      this.lsf.resetState();\n    } else {\n      this.lsf.resetAnnotationStore();\n    }\n\n    // Initial idea to show counter for Manual assignment only\n    // But currently we decided to hide it for any stream\n    // const distribution = this.project.assignment_settings.label_stream_task_distribution;\n    // const isManuallyAssigned = distribution === \"assigned_only\";\n\n    // undefined or true for backward compatibility\n    this.lsf.toggleInterface(\"postpone\", this.task.allow_postpone !== false);\n    this.lsf.toggleInterface(\"topbar:task-counter\", !isFF(FF_DEV_3734));\n    this.lsf.assignTask(task);\n    this.lsf.initializeStore(lsfTask);\n    this.setAnnotation(annotationID, fromHistory || isRejectedQueue);\n    this.setLoading(false);\n  }\n\n  /** @private */\n  setAnnotation(annotationID, selectAnnotation = false) {\n    const id = annotationID ? annotationID.toString() : null;\n    const { annotationStore: cs } = this.lsf;\n    let annotation;\n    const activeDrafts = cs.annotations.map((a) => a.draftId).filter(Boolean);\n\n    if (this.task.drafts) {\n      for (const draft of this.task.drafts) {\n        if (activeDrafts.includes(draft.id)) continue;\n        let c;\n\n        if (draft.annotation) {\n          // Annotation existed - add draft to existed annotation\n          const draftAnnotationPk = String(draft.annotation);\n\n          c = cs.annotations.find((c) => c.pk === draftAnnotationPk);\n          if (c) {\n            c.history.freeze();\n            c.addVersions({ draft: draft.result });\n            c.deleteAllRegions({ deleteReadOnly: true });\n          } else {\n            // that shouldn't happen\n            console.error(`No annotation found for pk=${draftAnnotationPk}`);\n            continue;\n          }\n        } else {\n          // Annotation not found - restore annotation from draft\n          c = cs.addAnnotation({\n            draft: draft.result,\n            userGenerate: true,\n            comment_count: draft.comment_count,\n            unresolved_comment_count: draft.unresolved_comment_count,\n            createdBy: draft.created_username,\n            createdAgo: draft.created_ago,\n            createdDate: draft.created_at,\n          });\n        }\n        cs.selectAnnotation(c.id);\n        c.deserializeResults(draft.result);\n        c.setDraftId(draft.id);\n        c.setDraftSaved(draft.created_at);\n        c.history.safeUnfreeze();\n        c.history.reinit();\n      }\n    }\n    const first = this.annotations?.length ? this.annotations[0] : null;\n    // if we have annotations created automatically, we don't need to create another one\n    // automatically === created here and haven't saved yet, so they don't have pk\n    // @todo because of some weird reason pk may be string uid, so check flags then\n    const hasAutoAnnotations = !!first && (!first.pk || (first.userGenerate && first.sentUserGenerate === false));\n    const showPredictions = this.project.show_collab_predictions === true;\n\n    if (this.labelStream) {\n      if (first?.draftId) {\n        // not submitted draft, most likely from previous labeling session\n        annotation = first;\n      } else if (isDefined(annotationID) && selectAnnotation) {\n        annotation = this.annotations.find(({ pk }) => pk === annotationID);\n      } else if (showPredictions && this.predictions.length > 0 && !this.isInteractivePreannotations) {\n        annotation = cs.addAnnotationFromPrediction(this.predictions[0]);\n      } else {\n        annotation = cs.createAnnotation();\n      }\n    } else {\n      if (this.annotations.length === 0 && this.predictions.length > 0 && !this.isInteractivePreannotations) {\n        const predictionByModelVersion = this.predictions.find((p) => p.createdBy === this.project.model_version);\n        annotation = cs.addAnnotationFromPrediction(predictionByModelVersion ?? this.predictions[0]);\n      } else if (this.annotations.length > 0 && id && id !== \"auto\") {\n        annotation = this.annotations.find((c) => c.pk === id || c.id === id);\n      } else if (this.annotations.length > 0 && (id === \"auto\" || hasAutoAnnotations)) {\n        annotation = first;\n      } else {\n        annotation = cs.createAnnotation();\n      }\n    }\n\n    if (annotation) {\n      cs.selectAnnotation(annotation.id);\n      this.datamanager.invoke(\"annotationSet\", annotation);\n    }\n  }\n\n  saveUserLabels = async () => {\n    const body = [];\n    const userLabels = this.lsf?.userLabels?.controls;\n\n    if (!userLabels) return;\n\n    for (const from_name in userLabels) {\n      for (const label of userLabels[from_name]) {\n        body.push({\n          value: label.path,\n          title: [from_name, JSON.stringify(label.path)].join(\":\"),\n          from_name,\n          project: this.project.id,\n        });\n      }\n    }\n\n    if (!body.length) return;\n\n    await this.datamanager.apiCall(\"saveUserLabels\", {}, { body });\n  };\n\n  async loadUserLabels() {\n    if (!this.lsf?.userLabels) return;\n\n    const userLabels = await this.datamanager.apiCall(\"userLabelsForProject\", {\n      project: this.project.id,\n      expand: \"label\",\n    });\n\n    if (!userLabels) return;\n\n    const controls = {};\n\n    for (const result of userLabels.results ?? []) {\n      // don't trust server's response!\n      if (!result?.label?.value?.length) continue;\n\n      const control = result.from_name;\n\n      if (!controls[control]) controls[control] = [];\n      controls[control].push(result.label.value);\n    }\n\n    this.lsf.userLabels.init(controls);\n  }\n\n  onLabelStudioLoad = async (ls) => {\n    this.datamanager.invoke(\"labelStudioLoad\", ls);\n    this.lsf = ls;\n\n    if (!this.lsf.task) this.setLoading(true);\n\n    const _taskHistory = await this.datamanager.store.taskStore.loadTaskHistory({\n      projectId: this.datamanager.store.project.id,\n    });\n\n    this.lsf.setTaskHistory(_taskHistory);\n\n    await this.loadUserLabels();\n\n    if (this.canPreloadTask && isFF(FF_DEV_1752)) {\n      await this.preloadTask();\n    } else if (this.labelStream) {\n      await this.loadTask();\n    }\n\n    this.setLoading(false);\n  };\n\n  /** @private */\n  onTaskLoad = async (...args) => {\n    this.datamanager.invoke(\"onSelectAnnotation\", ...args);\n  };\n\n  /**\n   * Proxy urls to presign them if storage is connected\n   * @param {*} _ LS instance\n   * @param {string} url http/https are not proxied and returned as is\n   */\n  onPresignUrlForProject = (_, url) => {\n    const parsedUrl = new URL(url);\n\n    // return same url if http(s)\n    if ([\"http:\", \"https:\"].includes(parsedUrl.protocol)) return url;\n\n    const api = this.datamanager.api;\n    const projectId = this.project.id;\n    const fileuri = btoa(url);\n\n    return api.createUrl(api.endpoints.presignUrlForProject, { projectId, fileuri }).url;\n  };\n\n  onStorageInitialized = async (ls) => {\n    this.datamanager.invoke(\"onStorageInitialized\", ls);\n\n    if (this.task && this.labelStream === false) {\n      const annotationID =\n        this.initialAnnotation?.pk ?? this.task.lastAnnotation?.pk ?? this.task.lastAnnotation?.id ?? \"auto\";\n\n      this.setAnnotation(annotationID);\n    }\n  };\n\n  /** @private */\n  onSubmitAnnotation = async () => {\n    const exitStream = this.shouldExitStream();\n    const loadNext = exitStream ? false : this.shouldLoadNext();\n    const result = await this.submitCurrentAnnotation(\n      \"submitAnnotation\",\n      async (taskID, body) => {\n        return await this.datamanager.apiCall(\n          \"submitAnnotation\",\n          { taskID },\n          { body },\n          // don't react on duplicated annotations error\n          { errorHandler: (result) => result.status === 409 },\n        );\n      },\n      false,\n      loadNext,\n    );\n    const status = result?.$meta?.status;\n\n    if (status === 200 || status === 201)\n      this.datamanager.invoke(\"toast\", { message: \"Annotation saved successfully\", type: \"info\" });\n    else if (status !== undefined)\n      this.datamanager.invoke(\"toast\", { message: \"There was an error saving your Annotation\", type: \"error\" });\n\n    if (exitStream) return this.exitStream();\n  };\n\n  /** @private */\n  onUpdateAnnotation = async (ls, annotation, extraData) => {\n    const { task } = this;\n    const serializedAnnotation = this.prepareData(annotation);\n    const exitStream = this.shouldExitStream();\n\n    Object.assign(serializedAnnotation, extraData);\n\n    await this.saveUserLabels();\n\n    const result = await this.withinLoadingState(async () => {\n      return this.datamanager.apiCall(\n        \"updateAnnotation\",\n        {\n          taskID: task.id,\n          annotationID: annotation.pk,\n        },\n        {\n          body: serializedAnnotation,\n        },\n      );\n    });\n    const status = result?.$meta?.status;\n\n    if (status === 200 || status === 201)\n      this.datamanager.invoke(\"toast\", { message: \"Annotation updated successfully\", type: \"info\" });\n    else if (status !== undefined)\n      this.datamanager.invoke(\"toast\", { message: \"There was an error updating your Annotation\", type: \"error\" });\n\n    this.datamanager.invoke(\"updateAnnotation\", ls, annotation, result);\n\n    if (exitStream) return this.exitStream();\n\n    const isRejectedQueue = isDefined(task.default_selected_annotation);\n\n    if (isRejectedQueue) {\n      // load next task if that one was updated task from rejected queue\n      await this.loadTask();\n    } else {\n      await this.loadTask(this.task.id, annotation.pk, true);\n    }\n  };\n\n  deleteDraft = async (id) => {\n    const response = await this.datamanager.apiCall(\"deleteDraft\", {\n      draftID: id,\n    });\n\n    this.task.deleteDraft(id);\n    return response;\n  };\n\n  /**@private */\n  onDeleteAnnotation = async (ls, annotation) => {\n    const { task } = this;\n    let response;\n\n    task.deleteAnnotation(annotation);\n\n    if (annotation.userGenerate && annotation.sentUserGenerate === false) {\n      if (annotation.draftId) {\n        response = await this.deleteDraft(annotation.draftId);\n      } else {\n        response = { ok: true };\n      }\n    } else {\n      response = await this.withinLoadingState(async () => {\n        return this.datamanager.apiCall(\"deleteAnnotation\", {\n          taskID: task.id,\n          annotationID: annotation.pk,\n        });\n      });\n\n      // this.task.deleteAnnotation(annotation);\n      this.datamanager.invoke(\"deleteAnnotation\", ls, annotation);\n    }\n\n    if (response.ok) {\n      const lastAnnotation = this.annotations[this.annotations.length - 1] ?? {};\n      const annotationID = lastAnnotation.pk ?? undefined;\n\n      this.setAnnotation(annotationID);\n    }\n  };\n\n  draftToast = (status) => {\n    if (status === 200 || status === 201)\n      this.datamanager.invoke(\"toast\", { message: \"Draft saved successfully\", type: \"info\" });\n    else if (status !== undefined)\n      this.datamanager.invoke(\"toast\", { message: \"There was an error saving your draft\", type: \"error\" });\n  };\n\n  needsDraftSave = (annotation) => {\n    if (annotation.history?.hasChanges && !annotation.draftSaved) return true;\n    if (\n      annotation.history?.hasChanges &&\n      new Date(annotation.history.lastAdditionTime) > new Date(annotation.draftSaved)\n    )\n      return true;\n    return false;\n  };\n\n  saveDraft = async (target = null) => {\n    const selected = target || this.lsf?.annotationStore?.selected;\n    const hasChanges = this.needsDraftSave(selected);\n\n    if (selected?.isDraftSaving) {\n      await when(() => !selected.isDraftSaving);\n      this.draftToast(200);\n    } else if (hasChanges && selected) {\n      const res = await selected?.saveDraftImmediatelyWithResults();\n      const status = res?.$meta?.status;\n\n      this.draftToast(status);\n    }\n  };\n\n  onSubmitDraft = async (studio, annotation, params = {}) => {\n    const annotationDoesntExist = !annotation.pk;\n    const data = { body: this.prepareData(annotation, { draft: true }) }; // serializedAnnotation\n    const hasChanges = this.needsDraftSave(annotation);\n    const showToast = params?.useToast && hasChanges;\n    // console.log('onSubmitDraft', params?.useToast, hasChanges);\n\n    if (params?.useToast) delete params.useToast;\n\n    Object.assign(data.body, params);\n\n    await this.saveUserLabels();\n\n    if (annotation.draftId > 0) {\n      // draft has been already created\n      const res = await this.datamanager.apiCall(\"updateDraft\", { draftID: annotation.draftId }, data);\n\n      showToast && this.draftToast(res?.$meta?.status);\n      return res;\n    }\n    let response;\n\n    if (annotationDoesntExist) {\n      response = await this.datamanager.apiCall(\"createDraftForTask\", { taskID: this.task.id }, data);\n    } else {\n      response = await this.datamanager.apiCall(\n        \"createDraftForAnnotation\",\n        { taskID: this.task.id, annotationID: annotation.pk },\n        data,\n      );\n    }\n    response?.id && annotation.setDraftId(response?.id);\n    showToast && this.draftToast(response?.$meta?.status);\n\n    return response;\n  };\n\n  onSkipTask = async (_, { comment } = {}) => {\n    await this.submitCurrentAnnotation(\n      \"skipTask\",\n      (taskID, body) => {\n        const { id, ...annotation } = body;\n        const params = { taskID };\n        const options = { body: annotation };\n\n        options.body.was_cancelled = true;\n        if (comment) options.body.comment = comment;\n\n        if (id === undefined) {\n          return this.datamanager.apiCall(\"submitAnnotation\", params, options);\n        }\n        params.annotationID = id;\n        return this.datamanager.apiCall(\"updateAnnotation\", params, options);\n      },\n      true,\n      this.shouldLoadNext(),\n    );\n  };\n\n  onUnskipTask = async () => {\n    const { task, currentAnnotation } = this;\n\n    if (!isDefined(currentAnnotation) && !isDefined(currentAnnotation.pk)) {\n      console.error(\"Annotation must be on unskip\");\n      return;\n    }\n\n    await this.withinLoadingState(async () => {\n      currentAnnotation.pauseAutosave();\n\n      if (isFF(FF_DEV_3034)) {\n        await this.datamanager.apiCall(\"convertToDraft\", {\n          annotationID: currentAnnotation.pk,\n        });\n      } else {\n        if (currentAnnotation.draftId > 0) {\n          await this.datamanager.apiCall(\n            \"updateDraft\",\n            {\n              draftID: currentAnnotation.draftId,\n            },\n            {\n              body: { annotation: null },\n            },\n          );\n        } else {\n          const annotationData = { body: this.prepareData(currentAnnotation) };\n\n          await this.datamanager.apiCall(\n            \"createDraftForTask\",\n            {\n              taskID: this.task.id,\n            },\n            annotationData,\n          );\n        }\n\n        // Carry over any comments to when the annotation draft is eventually submitted\n        if (isFF(FF_DEV_2887) && this.lsf?.commentStore?.toCache) {\n          this.lsf.commentStore.toCache(`task.${task.id}`);\n        }\n\n        await this.datamanager.apiCall(\"deleteAnnotation\", {\n          taskID: task.id,\n          annotationID: currentAnnotation.pk,\n        });\n      }\n    });\n    await this.loadTask(task.id);\n    this.datamanager.invoke(\"unskipTask\");\n  };\n\n  shouldLoadNext = () => {\n    if (!this.labelStream) return false;\n\n    // validating if URL is from notification, in case of notification it shouldn't load next task\n    const urlParam = new URLSearchParams(location.search).get(\"interaction\");\n\n    return urlParam !== \"notifications\";\n  };\n\n  shouldExitStream = () => {\n    const paramName = \"exitStream\";\n    const urlParam = new URLSearchParams(location.search).get(paramName);\n    const searchParams = new URLSearchParams(window.location.search);\n\n    searchParams.delete(paramName);\n    let newRelativePathQuery = window.location.pathname;\n\n    if (searchParams.toString()) newRelativePathQuery += `?${searchParams.toString()}`;\n    window.history.pushState(null, \"\", newRelativePathQuery);\n    return !!urlParam;\n  };\n\n  // Proxy events that are unused by DM integration\n  onEntityCreate = (...args) => this.datamanager.invoke(\"onEntityCreate\", ...args);\n  onEntityDelete = (...args) => this.datamanager.invoke(\"onEntityDelete\", ...args);\n  onSelectAnnotation = (prevAnnotation, nextAnnotation, options) => {\n    if (isFF(FF_OPTIC_2) && !!nextAnnotation?.history?.undoIdx) {\n      this.saveDraft(nextAnnotation).then(() => {\n        this.datamanager.invoke(\"onSelectAnnotation\", prevAnnotation, nextAnnotation, options, this);\n      });\n    } else {\n      this.datamanager.invoke(\"onSelectAnnotation\", prevAnnotation, nextAnnotation, options, this);\n    }\n  };\n\n  onNextTask = async (nextTaskId, nextAnnotationId) => {\n    if (isFF(FF_OPTIC_2)) this.saveDraft();\n    this.loadTask(nextTaskId, nextAnnotationId, true);\n  };\n  onPrevTask = async (prevTaskId, prevAnnotationId) => {\n    if (isFF(FF_OPTIC_2)) this.saveDraft();\n    this.loadTask(prevTaskId, prevAnnotationId, true);\n  };\n  async submitCurrentAnnotation(eventName, submit, includeId = false, loadNext = true) {\n    const { taskID, currentAnnotation } = this;\n    const unique_id = this.task.unique_lock_id;\n    const serializedAnnotation = this.prepareData(currentAnnotation, { includeId });\n\n    if (unique_id) {\n      serializedAnnotation.unique_id = unique_id;\n    }\n\n    this.setLoading(true);\n\n    await this.saveUserLabels();\n\n    const result = await this.withinLoadingState(async () => {\n      const result = await submit(taskID, serializedAnnotation);\n\n      return result;\n    });\n\n    if (result && result.id !== undefined) {\n      const annotationId = result.id.toString();\n\n      currentAnnotation.updatePersonalKey(annotationId);\n\n      const eventData = annotationToServer(currentAnnotation);\n\n      this.datamanager.invoke(eventName, this.lsf, eventData, result);\n\n      // Persist any queued comments which are not currently attached to an annotation\n      if (\n        isFF(FF_DEV_2887) &&\n        [\"submitAnnotation\", \"skipTask\"].includes(eventName) &&\n        this.lsf?.commentStore?.persistQueuedComments\n      ) {\n        await this.lsf.commentStore.persistQueuedComments();\n      }\n    }\n\n    this.setLoading(false);\n\n    if (!loadNext || this.datamanager.isExplorer) {\n      await this.loadTask(taskID, currentAnnotation.pk, true);\n    } else {\n      await this.loadTask();\n    }\n    return result;\n  }\n\n  /** @private */\n  prepareData(annotation, { includeId, draft } = {}) {\n    const userGenerate = !annotation.userGenerate || annotation.sentUserGenerate;\n\n    const sessionTime = (new Date() - annotation.loadedDate) / 1000;\n    const submittedTime = Number(annotation.leadTime ?? 0);\n    const draftTime = Number(this.task.drafts[0]?.lead_time ?? 0);\n    const lead_time = sessionTime + submittedTime + draftTime;\n\n    const result = {\n      lead_time,\n      result: (draft ? annotation.versions.draft : annotation.serializeAnnotation()) ?? [],\n      draft_id: annotation.draftId,\n      parent_prediction: annotation.parent_prediction,\n      parent_annotation: annotation.parent_annotation,\n    };\n\n    if (includeId && userGenerate) {\n      result.id = Number.parseInt(annotation.pk);\n    }\n\n    return result;\n  }\n\n  /** @private */\n  setLoading(isLoading, shouldReset = false) {\n    if (isFF(FF_LSDV_4620_3_ML) && shouldReset) this.lsf.clearApp();\n    this.lsf.setFlags({ isLoading });\n    if (isFF(FF_LSDV_4620_3_ML) && shouldReset) this.lsf.renderApp();\n  }\n\n  async withinLoadingState(callback) {\n    let result;\n\n    this.setLoading(true);\n    if (callback) {\n      result = await callback.call(this);\n    }\n    this.setLoading(false);\n\n    return result;\n  }\n\n  destroy() {\n    this.lsfInstance?.destroy?.();\n    this.lsfInstance = null;\n  }\n\n  get taskID() {\n    return this.task.id;\n  }\n\n  get taskHistory() {\n    return this.lsf.taskHistory;\n  }\n\n  get currentAnnotation() {\n    try {\n      return this.lsf.annotationStore.selected;\n    } catch {\n      return null;\n    }\n  }\n\n  get annotations() {\n    return this.lsf.annotationStore.annotations;\n  }\n\n  get predictions() {\n    return this.lsf.annotationStore.predictions;\n  }\n\n  /** @returns {string|null} */\n  get lsfConfig() {\n    return this.datamanager.store.labelingConfig;\n  }\n\n  /** @returns {Dict} */\n  get project() {\n    return this.datamanager.store.project;\n  }\n\n  /** @returns {string|null} */\n  get instruction() {\n    return (this.project.instruction ?? this.project.expert_instruction ?? \"\").trim() || null;\n  }\n\n  get canPreloadTask() {\n    return Boolean(this.preload?.interaction);\n  }\n}\n","/** @global LSF * /\n\n/**\n * @typedef {{\n *  hiddenColumns?: {\n *    labeling?: string[],\n *    explore?: string[],\n *  },\n *  visibleColumns?: {\n *    labeling?: string[],\n *    explore?: string[],\n *  }\n * }} TableConfig\n */\n\n/**\n * @typedef {{\n * root: HTMLElement,\n * polling: boolean,\n * apiGateway: string | URL,\n * apiEndpoints: import(\"../utils/api-proxy\").Endpoints,\n * apiMockDisabled: boolean,\n * apiHeaders?: Dict<string>,\n * settings: Dict<any>,\n * labelStudio: Dict<any>,\n * env: \"development\" | \"production\",\n * mode: \"labelstream\" | \"explorer\",\n * table: TableConfig,\n * links: Dict<string|null>,\n * showPreviews: boolean,\n * projectId?: number,\n * datasetId?: number,\n * interfaces: Dict<boolean>,\n * instruments: Dict<any>,\n * toolbar?: string,\n * spinner?: import(\"react\").ReactNode\n * apiTransform?: Record<string, Record<string, Function>\n * tabControls?: { add?: boolean, delete?: boolean, edit?: boolean, duplicate?: boolean },\n * }} DMConfig\n */\n\nimport { inject, observer } from \"mobx-react\";\nimport { destroy } from \"mobx-state-tree\";\nimport { unmountComponentAtNode } from \"react-dom\";\nimport { toCamelCase } from \"strman\";\nimport { instruments } from \"../components/DataManager/Toolbar/instruments\";\nimport { APIProxy } from \"../utils/api-proxy\";\nimport { FF_LSDV_4620_3_ML, isFF } from \"../utils/feature-flags\";\nimport { objectToMap } from \"../utils/helpers\";\nimport { serializeJsonForUrl, deserializeJsonFromUrl } from \"../utils/urlJSON\";\nimport { isDefined } from \"../utils/utils\";\nimport { APIConfig } from \"./api-config\";\nimport { createApp } from \"./app-create\";\nimport { LSFWrapper } from \"./lsf-sdk\";\nimport { taskToLSFormat } from \"./lsf-utils\";\n\nconst DEFAULT_TOOLBAR =\n  \"actions columns filters ordering label-button loading-possum error-box | refresh import-button export-button view-toggle\";\n\nconst prepareInstruments = (instruments) => {\n  const result = Object.entries(instruments).map(([name, builder]) => [name, builder({ inject, observer })]);\n\n  return objectToMap(Object.fromEntries(result));\n};\n\nexport class DataManager {\n  /** @type {HTMLElement} */\n  root = null;\n\n  /** @type {APIProxy} */\n  api = null;\n\n  /** @type {import(\"./lsf-sdk\").LSFWrapper} */\n  lsf = null;\n\n  /** @type {Dict} */\n  settings = {};\n\n  /** @type {import(\"../stores/AppStore\").AppStore} */\n  store = null;\n\n  /** @type {Dict<any>} */\n  labelStudioOptions = {};\n\n  /** @type {\"development\" | \"production\"} */\n  env = \"development\";\n\n  /** @type {\"explorer\" | \"labelstream\"} */\n  mode = \"explorer\";\n\n  /** @type {TableConfig} */\n  tableConfig = {};\n\n  /** @type {Dict<string|null>} */\n  links = {\n    import: \"/import\",\n    export: \"/export\",\n    settings: \"./settings\",\n  };\n\n  /**\n   * @private\n   * @type {Map<String, Set<Function>>}\n   */\n  callbacks = new Map();\n\n  /**\n   * @private\n   * @type {Map<String, Set<Function>>}\n   */\n  actions = new Map();\n\n  /** @type {Number} */\n  apiVersion = 1;\n\n  /** @type {boolean} */\n  showPreviews = false;\n\n  /** @type {boolean} */\n  polling = true;\n\n  /** @type {boolean} */\n  started = false;\n\n  instruments = new Map();\n\n  /**\n   * @type {DMConfig.tabControls}\n   */\n  tabControls = {\n    add: true,\n    delete: true,\n    edit: true,\n    duplicate: true,\n  };\n\n  /** @type {\"dm\" | \"labelops\"} */\n  type = \"dm\";\n\n  /**\n   * Constructor\n   * @param {DMConfig} config\n   */\n  constructor(config) {\n    this.root = config.root;\n    this.project = config.project;\n    this.projectId = config.projectId;\n    this.dataset = config.dataset;\n    this.datasetId = config.datasetId;\n    this.settings = config.settings;\n    this.labelStudioOptions = config.labelStudio;\n    this.env = config.env ?? process.env.NODE_ENV ?? this.env;\n    this.mode = config.mode ?? this.mode;\n    this.tableConfig = config.table ?? {};\n    this.apiVersion = config?.apiVersion ?? 1;\n    this.links = Object.assign(this.links, config.links ?? {});\n    this.showPreviews = config.showPreviews ?? false;\n    this.polling = config.polling;\n    this.toolbar = config.toolbar ?? DEFAULT_TOOLBAR;\n    this.spinner = config.spinner;\n    this.spinnerSize = config.spinnerSize;\n    this.instruments = prepareInstruments(config.instruments ?? {});\n    this.apiTransform = config.apiTransform ?? {};\n    this.preload = config.preload ?? {};\n    this.interfaces = objectToMap({\n      tabs: true,\n      toolbar: true,\n      import: true,\n      export: true,\n      labelButton: true,\n      backButton: true,\n      labelingHeader: true,\n      groundTruth: false,\n      instruction: false,\n      autoAnnotation: false,\n      ...config.interfaces,\n    });\n\n    this.api = new APIProxy(\n      this.apiConfig({\n        apiGateway: config.apiGateway,\n        apiEndpoints: config.apiEndpoints,\n        apiMockDisabled: config.apiMockDisabled,\n        apiSharedParams: config.apiSharedParams,\n        apiHeaders: config.apiHeaders,\n      }),\n    );\n\n    Object.assign(this.tabControls, config.tabControls ?? {});\n\n    this.updateActions(config.actions);\n\n    this.type = config.type ?? \"dm\";\n\n    this.initApp();\n  }\n\n  get isExplorer() {\n    return this.mode === \"labeling\";\n  }\n\n  get isLabelStream() {\n    return this.mode === \"labelstream\";\n  }\n\n  get projectId() {\n    return (this._projectId = this._projectId ?? this.root?.dataset?.projectId);\n  }\n\n  set projectId(value) {\n    this._projectId = value;\n  }\n\n  apiConfig({ apiGateway, apiEndpoints, apiMockDisabled, apiSharedParams, apiHeaders }) {\n    const config = Object.assign({}, APIConfig);\n\n    config.gateway = apiGateway ?? config.gateway;\n    config.mockDisabled = apiMockDisabled;\n    config.commonHeaders = apiHeaders;\n\n    Object.assign(config.endpoints, apiEndpoints ?? {});\n    const sharedParams = {};\n\n    if (!isNaN(this.projectId)) {\n      sharedParams.project = this.projectId;\n    }\n    if (!isNaN(this.datasetId)) {\n      sharedParams.dataset = this.datasetId;\n    }\n    Object.assign(config, {\n      sharedParams: {\n        ...sharedParams,\n        ...(apiSharedParams ?? {}),\n      },\n    });\n\n    return config;\n  }\n\n  /**\n   * @param {import(\"../stores/Action.js\").Action} action\n   */\n  addAction(action, callback) {\n    const { id } = action;\n\n    if (!id) throw new Error(\"Action must provide a unique ID\");\n\n    this.actions.set(id, { action, callback });\n\n    const actions = Array.from(this.actions.values()).map(({ action }) => action);\n\n    this.store?.setActions(actions);\n  }\n\n  removeAction(id) {\n    this.actions.delete(id);\n    this.store.removeAction(id);\n  }\n\n  getAction(id) {\n    return this.actions.get(id)?.callback;\n  }\n\n  installActions() {\n    this.actions.forEach(({ action, callback }) => {\n      this.addAction(action, callback);\n    });\n  }\n\n  updateActions(actions) {\n 